    sun: 0xfff0cf,
    ambient: 0xbfe0ff,
    ground: 0x58613a,
  },
}

export function terrainHeight(x, z, seed) {
  const ix = Math.floor(x)
  const iz = Math.floor(z)
  const broad = fbm2(ix * 0.0105, iz * 0.0105, seed, 5) - 0.5
  const detail = fbm2(ix * 0.048, iz * 0.048, seed + 17, 3) - 0.5
  let h = 20.6 + broad * 15.5 + detail * 3.2

  // A soft basin cradles the lake in front of the spawn point.
  const basin = Math.exp(-((ix * ix) / (2 * 27 * 27) + (iz * iz) / (2 * 24 * 24)))
  h -= basin * 8.2

  // A tiny forested island gives the lake a focal point.
  h += 6.4 * Math.exp(-((ix + 15) ** 2 + (iz + 3) ** 2) / (2 * 6.8 * 6.8))

  // Distant mountains rise beyond the opposite shore.
  const ridge = fbm2(ix * 0.0072 + 13.7, iz * 0.0072 - 4.1, seed + 73, 4)
  const far = smoothstep(26, 82, Math.hypot(ix, iz + 8))
  const mask = smoothstep(0.45, 0.7, ridge)
  h += mask * far * 25

  const p1 = 20 * Math.exp(-(((ix + 31) / 38) ** 2 + ((iz + 49) / 24) ** 2))
  const p2 = 16 * Math.exp(-(((ix - 47) / 30) ** 2 + ((iz + 57) / 22) ** 2))
  const p3 = 13 * Math.exp(-(((ix - 1) / 32) ** 2 + ((iz + 76) / 22) ** 2))
  h += (p1 + p2 + p3) * (1 - basin * 0.82)

  return Math.max(2, Math.floor(h))
}

function slopeAt(x, z, seed) {
  const h = terrainHeight(x, z, seed)
  return Math.max(
    Math.abs(h - terrainHeight(x + 1, z, seed)),
    Math.abs(h - terrainHeight(x - 1, z, seed)),
    Math.abs(h - terrainHeight(x, z + 1, seed)),
    Math.abs(h - terrainHeight(x, z - 1, seed)),
  )
}

const LANDMARK_TREES = [
  [-20, 15], [21, 23], [-15, -3], [30, 11], [-35, 27], [42, 30], [-7, 43], [18, 40],
]

function treeChance(x, z, seed) {
  const h = terrainHeight(x, z, seed)
  if (h <= SEA_LEVEL + 2 || h > 38) return 0
  if (slopeAt(x, z, seed) > 3) return 0
  const r = hash2(x, z, seed + 991)
  if (r < 0.0015 || r > 0.025) return 0
  const forest = fbm2(x * 0.019, z * 0.019, seed + 221, 3)
  const chance = forest > 0.53 ? 0.023 : forest > 0.47 ? 0.009 : 0.0025
  if (r > chance) return 0
  return h
}

function isLandmarkTree(x, z) {
  return LANDMARK_TREES.some(([tx, tz]) => tx === x && tz === z)
}

export class World {
  constructor(scene, seed = 20260214, renderDistance = 6) {
    this.scene = scene
    this.seed = seed
    this.renderDistance = renderDistance
    this.chunks = new Map()
    this.chunkMeshes = []
    this.dirty = new Set()
    this.time = 0
    this.worldGroup = new THREE.Group()
    this.worldGroup.name = 'VoxelWorld'
    scene.add(this.worldGroup)

    const maxAnisotropy = 4
    atlasTexture.anisotropy = maxAnisotropy
    this.opaqueMaterial = new THREE.MeshLambertMaterial({
      map: atlasTexture,
      vertexColors: true,
      alphaTest: 0.38,
      side: THREE.FrontSide,
    })
    this.plantMaterial = new THREE.MeshLambertMaterial({
      map: atlasTexture,
      vertexColors: true,
      alphaTest: 0.38,
      side: THREE.DoubleSide,
    })
    this.waterMaterial = new THREE.MeshPhongMaterial({
      map: atlasTexture,
      vertexColors: true,
      transparent: true,
      opacity: 0.78,
      depthWrite: false,
      shininess: 90,
      specular: 0x9edfff,
      side: THREE.DoubleSide,
    })
    this.clouds = null
  }

  key(cx, cz) {
    return `${cx},${cz}`
  }

  ensureData(cx, cz) {
    const k = this.key(cx, cz)
    let chunk = this.chunks.get(k)
    if (chunk) return chunk
    chunk = {
      cx, cz, key: k,
      data: this.generateChunk(cx, cz),
      mesh: null, plantMesh: null, waterMesh: null,
      dirty: false,
    }
    this.chunks.set(k, chunk)
    return chunk
  }

  generateChunk(cx, cz) {
    const data = new Uint8Array(CHUNK_VOLUME)
    const startX = cx * CHUNK_X
    const startZ = cz * CHUNK_Z
    const random = mulberry32((Math.imul(cx, 73856093) ^ Math.imul(cz, 19349663) ^ this.seed) >>> 0)

    for (let z = 0; z < CHUNK_Z; z++) {
      for (let x = 0; x < CHUNK_X; x++) {
        const wx = startX + x
        const wz = startZ + z
        const h = terrainHeight(wx, wz, this.seed)
        const slope = slopeAt(wx, wz, this.seed)
        const top = this.chooseTopBlock(wx, wz, h, slope)
        const underwater = h < SEA_LEVEL

        for (let y = 0; y <= h; y++) {
          let block
          if (y === 0) block = BLOCK.BEDROCK
          else if (y === h) block = top
          else if (y > h - 4) block = underwater ? BLOCK.SAND : h > 38 ? BLOCK.STONE : BLOCK.DIRT
          else block = BLOCK.STONE
          data[(y * CHUNK_Z + z) * CHUNK_X + x] = block
        }

        if (underwater) {
          for (let y = h + 1; y <= SEA_LEVEL && y < WORLD_HEIGHT; y++) {
            data[(y * CHUNK_Z + z) * CHUNK_X + x] = BLOCK.WATER
          }
        } else if (h + 1 < WORLD_HEIGHT) {
          const ground = data[(h * CHUNK_Z + z) * CHUNK_X + x]
          const canPlant = ground === BLOCK.GRASS && slope < 2
          const roll = random()
          if (canPlant && roll < 0.15) {
            data[((h + 1) * CHUNK_Z + z) * CHUNK_X + x] = BLOCK.TALL_GRASS
          } else if (canPlant && roll < 0.168) {
            data[((h + 1) * CHUNK_Z + z) * CHUNK_X + x] = BLOCK.POPPY
          } else if (canPlant && roll < 0.177) {
            data[((h + 1) * CHUNK_Z + z) * CHUNK_X + x] = BLOCK.DANDELION
          }
        }
      }
    }

    // Trees are evaluated just outside the chunk too, so canopies cross borders cleanly.
    for (let wz = startZ - 3; wz < startZ + CHUNK_Z + 3; wz++) {
      for (let wx = startX - 3; wx < startX + CHUNK_X + 3; wx++) {
        const landmark = isLandmarkTree(wx, wz)
        let base = landmark ? terrainHeight(wx, wz, this.seed) : treeChance(wx, wz, this.seed)
        if (!base && !landmark) continue
        if (base <= SEA_LEVEL + 1) {
          if (!landmark) continue
          base = SEA_LEVEL + 2
        }
        this.placeTree(data, cx, cz, wx, wz, base)
      }
    }

    return data
  }

  chooseTopBlock(wx, wz, h, slope) {
    const patch = fbm2(wx * 0.07, wz * 0.07, this.seed + 5, 2)
    if (h < SEA_LEVEL - 1) {
      return patch > 0.62 ? BLOCK.GRAVEL : BLOCK.SAND
    }
    if (h <= SEA_LEVEL + 1) return BLOCK.SAND
    if (h >= 43) return BLOCK.SNOW
    if (h >= 38 || slope >= 4) return patch > 0.58 ? BLOCK.MOSSY_COBBLE : BLOCK.STONE
    if (slope >= 3) return BLOCK.STONE
    return BLOCK.GRASS
  }

  placeTree(data, cx, cz, wx, wz, base) {
    const random = mulberry32((hash2(wx, wz, this.seed + 401) * 0xffffffff) >>> 0)
    const height = 4 + ((random() * 3) | 0)
    const top = base + height
    const startX = cx * CHUNK_X
    const startZ = cz * CHUNK_Z
    const set = (x, y, z, block, overwrite = false) => {
      const lx = x - startX
      const lz = z - startZ
      if (lx < 0 || lx >= CHUNK_X || lz < 0 || lz >= CHUNK_Z || y < 0 || y >= WORLD_HEIGHT) return
      const idx = (y * CHUNK_Z + lz) * CHUNK_X + lx
      if (!overwrite && data[idx] !== BLOCK.AIR) return
      data[idx] = block
    }

    // Low plants are replaced by the trunk.
    for (let y = base + 1; y <= top; y++) set(wx, y, wz, BLOCK.LOG, true)

    for (let dy = -2; dy <= 1; dy++) {
      const y = top + dy
      const radius = dy >= 0 ? 1 : 2
      for (let dz = -radius; dz <= radius; dz++) {
        for (let dx = -radius; dx <= radius; dx++) {
          if (dx === 0 && dz === 0 && y <= top) continue
          if (Math.abs(dx) === radius && Math.abs(dz) === radius && random() > 0.28) continue
          set(wx + dx, y, wz + dz, BLOCK.LEAVES)
        }
      }
    }
    set(wx, top + 2, wz, BLOCK.LEAVES)
    set(wx, top + 3, wz, BLOCK.LEAVES)
  }

  getBlock(wx, wy, wz) {
    if (wy < 0) return BLOCK.BEDROCK
    if (wy >= WORLD_HEIGHT) return BLOCK.AIR
    const cx = Math.floor(wx / CHUNK_X)
    const cz = Math.floor(wz / CHUNK_Z)
    const chunk = this.ensureData(cx, cz)
    const lx = ((wx % CHUNK_X) + CHUNK_X) % CHUNK_X
    const lz = ((wz % CHUNK_Z) + CHUNK_Z) % CHUNK_Z
    return chunk.data[(wy * CHUNK_Z + lz) * CHUNK_X + lx]
  }

  isSolid(wx, wy, wz) {
    return BLOCKS[this.getBlock(wx, wy, wz)].solid
  }

  setBlock(wx, wy, wz, block) {
    if (wy <= 0 || wy >= WORLD_HEIGHT) return false
    const cx = Math.floor(wx / CHUNK_X)
    const cz = Math.floor(wz / CHUNK_Z)
    const chunk = this.ensureData(cx, cz)
    const lx = ((wx % CHUNK_X) + CHUNK_X) % CHUNK_X
    const lz = ((wz % CHUNK_Z) + CHUNK_Z) % CHUNK_Z
    chunk.data[(wy * CHUNK_Z + lz) * CHUNK_X + lx] = block
    this.markDirty(cx, cz)
    if (lx === 0) this.markDirty(cx - 1, cz)
    if (lx === CHUNK_X - 1) this.markDirty(cx + 1, cz)
    if (lz === 0) this.markDirty(cx, cz - 1)
    if (lz === CHUNK_Z - 1) this.markDirty(cx, cz + 1)
    return true
  }

  markDirty(cx, cz) {
    const key = this.key(cx, cz)
    const chunk = this.chunks.get(key)
    if (chunk) this.dirty.add(key)
  }

  ensureArea(centerX, centerZ, radius) {
    // Data first, then meshes, keeps border face queries cheap and deterministic.
    for (let dz = -radius; dz <= radius; dz++) {
      for (let dx = -radius; dx <= radius; dx++) {
        this.ensureData(centerX + dx, centerZ + dz)
      }
    }
    for (let dz = -radius; dz <= radius; dz++) {
      for (let dx = -radius; dx <= radius; dx++) {
        const key = this.key(centerX + dx, centerZ + dz)
        const chunk = this.chunks.get(key)
        if (chunk && !chunk.mesh) this.buildChunk(chunk)
      }
    }
  }

  buildChunk(chunk) {
    const { data, cx, cz } = chunk
    const solid = { pos: [], norm: [], uv: [], color: [], idx: [] }
    const plants = { pos: [], norm: [], uv: [], color: [], idx: [] }
    const water = { pos: [], norm: [], uv: [], color: [], idx: [] }
    const startX = cx * CHUNK_X
    const startZ = cz * CHUNK_Z
    const blockAt = (x, y, z) => {
      if (x < 0 || x >= CHUNK_X || z < 0 || z >= CHUNK_Z || y < 0 || y >= WORLD_HEIGHT) {
        return this.getBlock(startX + x, y, startZ + z)
      }
      return data[(y * CHUNK_Z + z) * CHUNK_X + x]
    }

    const isOccluder = (x, y, z) => BLOCKS[blockAt(x, y, z)].solid

    for (let y = 0; y < WORLD_HEIGHT; y++) {
      for (let z = 0; z < CHUNK_Z; z++) {
        for (let x = 0; x < CHUNK_X; x++) {
          const id = data[(y * CHUNK_Z + z) * CHUNK_X + x]
          if (id === BLOCK.AIR) continue
          const definition = BLOCKS[id]

          if (definition.plant) {
            this.addPlant(plants, x, y, z, id)
            continue
          }

          if (definition.liquid) {
            for (const face of FACES) {
              const [nx, ny, nz] = face.normal
              const neighbor = blockAt(x + nx, y + ny, z + nz)
              if (neighbor !== BLOCK.AIR) continue
              this.addFace(water, x, y, z, face, BLOCK.WATER, 1, 0.9)
            }
            continue
          }

          for (const face of FACES) {
            const [nx, ny, nz] = face.normal
            const neighbor = blockAt(x + nx, y + ny, z + nz)
            const neighborDef = BLOCKS[neighbor]
            let visible = !neighborDef.solid
            if (neighbor === BLOCK.LEAVES && id === BLOCK.LEAVES) visible = false
            if (!visible) continue
            const tile = definition.tiles[face.cornerName]
            const ao = this.ambientOcclusion(x, y, z, face, isOccluder)
            this.addFace(solid, x, y, z, face, tile, 1, 1, ao)
          }
        }
      }
    }

    this.finishChunkMesh(chunk, 'mesh', solid, this.opaqueMaterial, true)
    this.finishChunkMesh(chunk, 'plantMesh', plants, this.plantMaterial, false)
    this.finishChunkMesh(chunk, 'waterMesh', water, this.waterMaterial, false)
    chunk.dirty = false
  }

  ambientOcclusion(x, y, z, face, isOccluder) {
    const axis = face.axis
    const normal = face.normal
    const bx = x + normal[0]
    const by = y + normal[1]
    const bz = z + normal[2]
    const otherAxes = [0, 1, 2].filter((a) => a !== axis)
    const result = []
    for (const v of face.vertices) {
      const p = [0, 0, 0]
      p[axis] = normal[axis]
      const signs = []
      for (const a of otherAxes) {
        const sign = v[a] ? 1 : -1
        p[a] = sign
        signs.push([a, sign])
      }
      const p1 = [bx + (signs[0][0] === 0 ? 0 : 0), by, bz]
      const s1 = [0, 0, 0]
      s1[signs[0][0]] += signs[0][1]
      const s2 = [0, 0, 0]
      s2[signs[1][0]] += signs[1][1]
      const occ1 = isOccluder(bx + s1[0], by + s1[1], bz + s1[2]) ? 1 : 0
      const occ2 = isOccluder(bx + s2[0], by + s2[1], bz + s2[2]) ? 1 : 0
      const cor = isOccluder(bx + s1[0] + s2[0], by + s1[1] + s2[1], bz + s1[2] + s2[2]) ? 1 : 0
      let brightness
      if (occ1 && occ2) brightness = 0.55
      else brightness = 1 - 0.14 * (occ1 + occ2 + cor)
      result.push(brightness)
    }
    return result
  }

  addFace(target, x, y, z, face, tile, alpha, shade, ao = null) {
    const [u0, v0, u1, v1] = uvRect(tile)
    const base = target.pos.length / 3
    for (let i = 0; i < 4; i++) {
      const v = face.vertices[i]
      target.pos.push(x + v[0], y + v[1], z + v[2])
      target.norm.push(face.normal[0], face.normal[1], face.normal[2])
      const c = (ao ? ao[i] : 1) * face.shade * shade
      target.color.push(c, c, c)
    }
    target.uv.push(u0, v0, u1, v0, u1, v1, u0, v1)
    target.idx.push(base, base + 1, base + 2, base, base + 2, base + 3)
  }

  addPlant(target, x, y, z, id) {
    const [u0, v0, u1, v1] = uvRect(BLOCKS[id].tiles.top)
    const planes = [
      [[0.1, 0, 0.1], [0.9, 0, 0.9]],
      [[0.9, 0, 0.1], [0.1, 0, 0.9]],
    ]
    for (const [a, b] of planes) {
      for (let side = 0; side < 2; side++) {
        const base = target.pos.length / 3
        const verts = side === 0
          ? [[a[0], 0, a[2]], [b[0], 0, b[2]], [b[0], 1, b[2]], [a[0], 1, a[2]]]
          : [[b[0], 0, b[2]], [a[0], 0, a[2]], [a[0], 1, a[2]], [b[0], 1, b[2]]]
        for (const v of verts) {
          target.pos.push(x + v[0], y + v[1], z + v[2])
          target.norm.push(0, 1, 0)
          const c = 0.98
          target.color.push(c, c, c)
        }
        target.uv.push(u0, v0, u1, v0, u1, v1, u0, v1)
        target.idx.push(base, base + 1, base + 2, base, base + 2, base + 3)
      }
    }
  }

  finishChunkMesh(chunk, slot, target, material, castShadow) {
    const old = chunk[slot]
    if (old) {
      this.worldGroup.remove(old)
      old.geometry.dispose()
      const i = this.chunkMeshes.indexOf(old)
      if (i >= 0) this.chunkMeshes.splice(i, 1)
      chunk[slot] = null
    }
    if (!target.idx.length) return
    const geometry = new THREE.BufferGeometry()
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(target.pos, 3))
    geometry.setAttribute('normal', new THREE.Float32BufferAttribute(target.norm, 3))
    geometry.setAttribute('uv', new THREE.Float32BufferAttribute(target.uv, 2))
    geometry.setAttribute('color', new THREE.Float32BufferAttribute(target.color, 3))
    geometry.setIndex(target.idx)
    geometry.computeBoundingSphere()
    geometry.computeBoundingBox()
    const mesh = new THREE.Mesh(geometry, material)
    mesh.position.set(chunk.cx * CHUNK_X, 0, chunk.cz * CHUNK_Z)
    mesh.castShadow = castShadow
    mesh.receiveShadow = true
    mesh.matrixAutoUpdate = false
    mesh.updateMatrix()
    mesh.userData.chunk = chunk
    mesh.userData.slot = slot
    chunk[slot] = mesh
    this.worldGroup.add(mesh)
    this.chunkMeshes.push(mesh)
  }

  rebuildDirty() {
    if (!this.dirty.size) return
    for (const key of this.dirty) {
      const chunk = this.chunks.get(key)
      if (!chunk) continue
      this.buildChunk(chunk)
    }
    this.dirty.clear()
  }

  update(playerPosition, radius = this.renderDistance) {
    this.time += 0.016
    const cx = Math.floor(playerPosition.x / CHUNK_X)
    const cz = Math.floor(playerPosition.z / CHUNK_Z)
    if (this.lastCx !== cx || this.lastCz !== cz) {
      this.lastCx = cx
      this.lastCz = cz
      this.ensureArea(cx, cz, radius)
    }
    this.rebuildDirty()

    // Trim far meshes while keeping their block data for fast backtracking.
    const maxDist = (radius + 2.5) * CHUNK_X
    for (const chunk of this.chunks.values()) {
      if (!chunk.mesh) continue
      const dx = (chunk.cx + 0.5) * CHUNK_X - playerPosition.x
      const dz = (chunk.cz + 0.5) * CHUNK_Z - playerPosition.z
      if (dx * dx + dz * dz > maxDist * maxDist) {
        this.removeMeshes(chunk)
      }
    }
  }

  removeMeshes(chunk) {
    for (const slot of ['mesh', 'plantMesh', 'waterMesh']) {
      const mesh = chunk[slot]
      if (!mesh) continue
      this.worldGroup.remove(mesh)
      mesh.geometry.dispose()
      const i = this.chunkMeshes.indexOf(mesh)
      if (i >= 0) this.chunkMeshes.splice(i, 1)
      chunk[slot] = null
    }
  }

  findSpawn() {
    let best = null
    for (let radius = 0; radius < 48; radius++) {
      const steps = radius === 0 ? 1 : Math.max(10, radius * 6)
      for (let i = 0; i < steps; i++) {
        const angle = (i / steps) * Math.PI * 2
        const x = Math.round(Math.cos(angle) * radius)
        const z = Math.round(32 + Math.sin(angle) * radius * 0.72)
        const h = terrainHeight(x, z, this.seed)
        const slope = slopeAt(x, z, this.seed)
        if (h <= SEA_LEVEL + 2 || h > SEA_LEVEL + 10 || slope > 2) continue
        best = new THREE.Vector3(x + 0.5, h + 1.02, z + 0.5)
        if (Math.abs(x) < 6) return best
      }
    }
    return best || new THREE.Vector3(0.5, SEA_LEVEL + 4.2, 32.5)
  }

  surfaceHeight(x, z) {
    for (let y = WORLD_HEIGHT - 1; y >= 0; y--) {
      const block = this.getBlock(Math.floor(x), y, Math.floor(z))
      if (BLOCKS[block].solid) return y + 1
    }
    return 0
  }

  topBlock(x, z) {
    const cx = Math.floor(x / CHUNK_X)
    const cz = Math.floor(z / CHUNK_Z)
    const chunk = this.ensureData(cx, cz)
    const lx = ((Math.floor(x) % CHUNK_X) + CHUNK_X) % CHUNK_X
    const lz = ((Math.floor(z) % CHUNK_Z) + CHUNK_Z) % CHUNK_Z
    for (let y = WORLD_HEIGHT - 1; y >= 0; y--) {
      const id = chunk.data[(y * CHUNK_Z + lz) * CHUNK_X + lx]
      if (id !== BLOCK.AIR) return id
    }
    return BLOCK.AIR
  }
}

import * as THREE from 'three'
import { mulberry32 } from './noise.js'

const SKY_VERTEX = `
  varying vec3 vWorldDirection;
  void main() {
    vec4 worldPosition = modelMatrix * vec4(position, 1.0);
    vWorldDirection = normalize(worldPosition.xyz - cameraPosition);
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`

const SKY_FRAGMENT = `
  uniform vec3 topColor;
  uniform vec3 horizonColor;
  uniform vec3 sunColor;
  uniform vec3 sunDirection;
  varying vec3 vWorldDirection;

  void main() {
    vec3 dir = normalize(vWorldDirection);
    float h = smoothstep(-0.08, 0.72, dir.y);
    vec3 col = mix(horizonColor, topColor, h);

    float sunDot = max(dot(dir, sunDirection), 0.0);
    float disc = pow(sunDot, 1450.0);
    float halo = pow(sunDot, 14.0) * 0.16 + pow(sunDot, 4.0) * 0.055;
    col += sunColor * disc * 1.5;
    col += sunColor * halo;
    gl_FragColor = vec4(col, 1.0);
  }
`

function makeClouds(scene, seed) {
  const random = mulberry32(seed)
  const cells = []
  const clusters = 16
  for (let i = 0; i < clusters; i++) {
    const angle = random() * Math.PI * 2
    const dist = 55 + random() * 140
    const cx = Math.cos(angle) * dist
    const cz = Math.sin(angle) * dist
    const cy = 72 + random() * 9
    const count = 4 + ((random() * 6) | 0)
    for (let j = 0; j < count; j++) {
      const sx = 4 + random() * 8
      const sz = 3 + random() * 6
      const sy = 2 + random() * 2.2
      cells.push({
        x: cx + (random() - 0.5) * 20,
        y: cy + (random() - 0.5) * 2.2,
        z: cz + (random() - 0.5) * 15,
        sx, sy, sz,
      })
    }
  }

  const geometry = new THREE.BoxGeometry(1, 1, 1)
  const material = new THREE.MeshLambertMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 0.82,
    depthWrite: false,
    emissive: 0x46515c,
    emissiveIntensity: 0.22,
  })
  const mesh = new THREE.InstancedMesh(geometry, material, cells.length)
  mesh.frustumCulled = false
  const matrix = new THREE.Matrix4()
  const color = new THREE.Color()
  cells.forEach((cell, index) => {
    matrix.compose(
      new THREE.Vector3(cell.x, cell.y, cell.z),
      new THREE.Quaternion(),
      new THREE.Vector3(cell.sx, cell.sy, cell.sz),
    )
    mesh.setMatrixAt(index, matrix)
    const tint = 0.9 + random() * 0.1
    color.setRGB(tint, tint, tint)
    mesh.setColorAt(index, color)
  })
  mesh.instanceMatrix.needsUpdate = true
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true
  scene.add(mesh)
  return mesh
}

function makeDust(scene) {
  const count = 180
  const positions = new Float32Array(count * 3)
  const random = mulberry32(424242)
  const data = []
  for (let i = 0; i < count; i++) {
    const p = {
      x: (random() - 0.5) * 34,
      y: random() * 9,
      z: (random() - 0.5) * 34,
      speed: 0.06 + random() * 0.14,
      phase: random() * Math.PI * 2,
    }
    data.push(p)
    positions[i * 3] = p.x
    positions[i * 3 + 1] = p.y
    positions[i * 3 + 2] = p.z
  }
  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
  const material = new THREE.PointsMaterial({
    color: 0xfff4c8,
    size: 0.075,
    transparent: true,
    opacity: 0.62,
    depthWrite: false,
    sizeAttenuation: true,
  })
  const points = new THREE.Points(geometry, material)
  points.frustumCulled = false
  scene.add(points)
  return { points, data, positions }
}

export function createEnvironment(scene, renderer) {
  renderer.shadowMap.enabled = true
  renderer.shadowMap.type = THREE.PCFSoftShadowMap
  renderer.toneMapping = THREE.ACESFilmicToneMapping
  renderer.toneMappingExposure = 1.16
  renderer.outputColorSpace = THREE.SRGBColorSpace

  const skyMaterial = new THREE.ShaderMaterial({
    uniforms: {
      topColor: { value: new THREE.Color(0x4a9ce3) },
      horizonColor: { value: new THREE.Color(0xd6efff) },
      sunColor: { value: new THREE.Color(0xfff2cc) },
      sunDirection: { value: new THREE.Vector3(-0.45, 0.62, -0.64).normalize() },
    },
    vertexShader: SKY_VERTEX,
    fragmentShader: SKY_FRAGMENT,
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
  })
  const sky = new THREE.Mesh(new THREE.SphereGeometry(430, 32, 18), skyMaterial)
  sky.name = 'Sky'
  scene.add(sky)

  scene.fog = new THREE.Fog(0xb9dcec, 52, 152)

  const hemisphere = new THREE.HemisphereLight(0xc4e5ff, 0x536138, 1.48)
  scene.add(hemisphere)

  const sun = new THREE.DirectionalLight(0xfff1d2, 2.45)
  sun.position.set(-44, 74, -36)
  sun.castShadow = true
  sun.shadow.mapSize.set(2048, 2048)
  sun.shadow.camera.near = 1
  sun.shadow.camera.far = 190
  sun.shadow.camera.left = -54
  sun.shadow.camera.right = 54
  sun.shadow.camera.top = 54
  sun.shadow.camera.bottom = -54
  sun.shadow.bias = -0.00035
  sun.shadow.normalBias = 0.025
  sun.target.position.set(0, 20, 0)
  scene.add(sun)
  scene.add(sun.target)

  const fill = new THREE.DirectionalLight(0x8dbce8, 0.38)
  fill.position.set(55, 35, 50)
  scene.add(fill)

  const clouds = makeClouds(scene, 7771)
  const dust = makeDust(scene)
  const clock = new THREE.Clock()
  const baseCloudX = clouds.position.x
  let elapsed = 0

  function update(playerPosition) {
    const dt = Math.min(clock.getDelta(), 0.05)
    elapsed += dt
    sky.position.copy(playerPosition)
    clouds.position.x = baseCloudX + Math.sin(elapsed * 0.006) * 34

    sun.position.set(playerPosition.x - 44, playerPosition.y + 74, playerPosition.z - 36)
    sun.target.position.set(playerPosition.x, playerPosition.y + 5, playerPosition.z)
    sun.target.updateMatrixWorld()

    dust.points.position.set(
      Math.floor(playerPosition.x / 34) * 34,
      Math.max(0, Math.floor(playerPosition.y / 9) * 9),
      Math.floor(playerPosition.z / 34) * 34,
    )
    const positions = dust.positions
    for (let i = 0; i < dust.data.length; i++) {
      const p = dust.data[i]
      positions[i * 3] = p.x + Math.sin(elapsed * p.speed + p.phase) * 1.4
      positions[i * 3 + 1] = p.y + Math.sin(elapsed * p.speed * 0.7 + p.phase) * 0.7
      positions[i * 3 + 2] = p.z + Math.cos(elapsed * p.speed * 0.8 + p.phase) * 1.2
    }
    dust.points.geometry.attributes.position.needsUpdate = true
    return dt
  }

  return {
    update,
    sky,
    sun,
    hemisphere,
    clouds,
    dust,
    sunDirection: skyMaterial.uniforms.sunDirection.value,
  }
}

// Tiny procedural sound engine. No audio files are needed.
export class AudioEngine {
  constructor() {
    this.ctx = null
    this.master = null
    this.muted = false
    this.noise = null
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume()
      return
    }
    const AudioContext = window.AudioContext || window.webkitAudioContext
    if (!AudioContext) return
    this.ctx = new AudioContext()
    this.master = this.ctx.createGain()
    this.master.gain.value = 0.42
    this.master.connect(this.ctx.destination)
    const length = this.ctx.sampleRate * 1.2
    this.noise = this.ctx.createBuffer(1, length, this.ctx.sampleRate)
    const data = this.noise.getChannelData(0)
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1
  }

  setMuted(value) {
    this.muted = value
    if (this.master) this.master.gain.setTargetAtTime(value ? 0 : 0.42, this.ctx.currentTime, 0.02)
  }

  burst({ duration = 0.12, volume = 0.25, frequency = 800, q = 0.8, type = 'lowpass', delay = 0, pitch = 1 }) {
    if (!this.ctx || this.muted) return
    const now = this.ctx.currentTime + delay
    const source = this.ctx.createBufferSource()
    source.buffer = this.noise
    source.playbackRate.value = pitch
    const filter = this.ctx.createBiquadFilter()
    filter.type = type
    filter.frequency.setValueAtTime(frequency, now)
    filter.Q.value = q
    const gain = this.ctx.createGain()
    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.008)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration)
    source.connect(filter)
    filter.connect(gain)
    gain.connect(this.master)
    source.start(now)
    source.stop(now + duration + 0.02)
  }

  tone({ frequency = 220, endFrequency = frequency, duration = 0.08, volume = 0.15, type = 'sine', delay = 0 }) {
    if (!this.ctx || this.muted) return
    const now = this.ctx.currentTime + delay
    const oscillator = this.ctx.createOscillator()
    oscillator.type = type
    oscillator.frequency.setValueAtTime(frequency, now)
    oscillator.frequency.exponentialRampToValueAtTime(Math.max(20, endFrequency), now + duration)
    const gain = this.ctx.createGain()
    gain.gain.setValueAtTime(0.0001, now)
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.006)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration)
    oscillator.connect(gain)
    gain.connect(this.master)
    oscillator.start(now)
    oscillator.stop(now + duration + 0.03)
  }

  step(surface = 'grass') {
    const soft = surface === 'sand' || surface === 'snow'
    this.burst({
      duration: soft ? 0.09 : 0.075,
      volume: soft ? 0.07 : 0.11,
      frequency: soft ? 520 : surface === 'stone' ? 1250 : 760,
      q: 0.6,
      pitch: 0.8 + Math.random() * 0.35,
    })
  }

  jump() {
    this.tone({ frequency: 150, endFrequency: 100, duration: 0.09, volume: 0.04, type: 'triangle' })
  }

  breakBlock(blockName = '') {
    const stony = /stone|cobble|brick|bedrock/i.test(blockName)
    this.burst({ duration: 0.18, volume: 0.22, frequency: stony ? 1700 : 820, pitch: 0.9 + Math.random() * 0.3 })
    this.tone({ frequency: stony ? 170 : 110, endFrequency: 60, duration: 0.13, volume: 0.14, type: 'triangle' })
  }

  placeBlock() {
    this.burst({ duration: 0.075, volume: 0.13, frequency: 1300, q: 0.7 })
    this.tone({ frequency: 240, endFrequency: 150, duration: 0.06, volume: 0.06, type: 'square' })
  }

  select() {
    this.tone({ frequency: 520, endFrequency: 680, duration: 0.045, volume: 0.035, type: 'triangle' })
  }

  splash() {
    this.burst({ duration: 0.35, volume: 0.16, frequency: 650, q: 0.4, type: 'bandpass', pitch: 0.7 })
  }

  hurt() {
    this.tone({ frequency: 180, endFrequency: 75, duration: 0.22, volume: 0.14, type: 'sawtooth' })
    this.burst({ duration: 0.12, volume: 0.08, frequency: 500 })
  }

  click() {
    this.tone({ frequency: 300, endFrequency: 360, duration: 0.03, volume: 0.03, type: 'square' })
  }
}

import * as THREE from 'three'
import { BLOCKS } from './blocks.js'

const cubeGeometry = new THREE.BoxGeometry(1, 1, 1)
const splashGeometry = new THREE.BoxGeometry(1, 0.65, 1)

export class Effects {
  constructor(scene) {
    this.scene = scene
    this.particles = []
    this.materials = new Map()
  }

  materialFor(color, opacity = 1) {
    const key = `${color}-${opacity}`
    if (!this.materials.has(key)) {
      this.materials.set(key, new THREE.MeshLambertMaterial({ color, transparent: true, opacity }))
    }
    return this.materials.get(key)
  }

  burst(x, y, z, blockId, count = 14, power = 3.2) {
    const block = BLOCKS[blockId]
    const color = new THREE.Color(block?.mapColor || '#9b8b70')
    const material = this.materialFor(color.getHex())
    for (let i = 0; i < count; i++) {
      const mesh = new THREE.Mesh(cubeGeometry, material)
      const size = 0.06 + Math.random() * 0.1
      mesh.scale.setScalar(size)
      mesh.position.set(
        x + 0.2 + Math.random() * 0.6,
        y + 0.2 + Math.random() * 0.6,
        z + 0.2 + Math.random() * 0.6,
      )
      mesh.castShadow = false
      mesh.receiveShadow = true
      const angle = Math.random() * Math.PI * 2
      const speed = power * (0.35 + Math.random() * 0.8)
      this.particles.push({
        mesh,
        vx: Math.cos(angle) * speed,
        vy: 1.5 + Math.random() * power,
        vz: Math.sin(angle) * speed,
        life: 0.45 + Math.random() * 0.55,
        maxLife: 1,
        spin: (Math.random() - 0.5) * 8,
      })
      this.scene.add(mesh)
    }
  }

  splash(x, y, z, count = 22) {
    const material = this.materialFor(0x8fd4ff, 0.88)
    for (let i = 0; i < count; i++) {
      const mesh = new THREE.Mesh(splashGeometry, material)
      const size = 0.09 + Math.random() * 0.12
      mesh.scale.set(size, size, size)
      mesh.position.set(x + (Math.random() - 0.5) * 1.4, y, z + (Math.random() - 0.5) * 1.4)
      const angle = Math.random() * Math.PI * 2
      const speed = 0.8 + Math.random() * 2.6
      this.particles.push({
        mesh,
        vx: Math.cos(angle) * speed,
        vy: 2.2 + Math.random() * 3.2,
        vz: Math.sin(angle) * speed,
        life: 0.5 + Math.random() * 0.4,
        maxLife: 0.9,
        spin: (Math.random() - 0.5) * 9,
      })
      this.scene.add(mesh)
    }
  }

  update(dt) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i]
      p.life -= dt
      if (p.life <= 0) {
        this.scene.remove(p.mesh)
        this.particles.splice(i, 1)
        continue
      }
      p.vy -= 17 * dt
      p.mesh.position.x += p.vx * dt
      p.mesh.position.y += p.vy * dt
      p.mesh.position.z += p.vz * dt
      p.mesh.rotation.x += p.spin * dt
      p.mesh.rotation.z += p.spin * 0.7 * dt
      const fade = Math.min(1, p.life / 0.22)
      p.mesh.scale.multiplyScalar(0.985)
      p.mesh.material.opacity = fade
    }
  }

  clear() {
    for (const p of this.particles) this.scene.remove(p.mesh)
    this.particles.length = 0
  }
}

import * as THREE from 'three'
import { BLOCK, BLOCKS } from './blocks.js'
import { makeCrackTextures } from './textures.js'

const GRAVITY = 27
const WALK_SPEED = 5.3
const SPRINT_SPEED = 7.7
const FLY_SPEED = 11
const PLAYER_WIDTH = 0.62
const PLAYER_HEIGHT = 1.8
const EYE_HEIGHT = 1.62
const REACH = 6.2

const BREAK_TIME = {
  [BLOCK.GRASS]: 0.24,
  [BLOCK.DIRT]: 0.26,
  [BLOCK.SAND]: 0.22,
  [BLOCK.GRAVEL]: 0.26,
  [BLOCK.STONE]: 0.5,
  [BLOCK.COBBLE]: 0.48,
  [BLOCK.MOSSY_COBBLE]: 0.48,
  [BLOCK.BRICK]: 0.52,
  [BLOCK.LOG]: 0.4,
  [BLOCK.PLANKS]: 0.36,
  [BLOCK.LEAVES]: 0.12,
  [BLOCK.SNOW]: 0.16,
}

export class Player {
  constructor({ world, scene, camera, spawn, audio, effects }) {
    this.world = world
    this.scene = scene
    this.camera = camera
    this.audio = audio
    this.effects = effects
    this.spawn = spawn.clone()
    this.position = spawn.clone()
    this.velocity = new THREE.Vector3()
    this.yaw = 0
    this.pitch = -0.12
    this.onGround = false
    this.flying = false
    this.inWater = false
    this.headInWater = false
    this.health = 20
    this.maxHealth = 20
    this.oxygen = 300
    this.dead = false
    this.input = {
      forward: false, back: false, left: false, right: false,
      jump: false, sprint: false, descend: false,
      touchForward: 0, touchRight: 0,
    }
    this.walkPhase = 0
    this.stepDistance = 0
    this.bob = 0
    this.roll = 0
    this.target = null
    this.miningProgress = 0
    this.miningKey = ''
    this.lastDamage = -99
    this.airTime = 0
    this.peakY = spawn.y
    this.drownTimer = 0
    this.onDamage = null
    this.onDeath = null
    this.onHealthChanged = null
    this.onFootstep = null
    this.selected = BLOCK.GRASS
    this.fov = 70
    this.shake = 0
    this.tmp = new THREE.Vector3()

    this.raycaster = new THREE.Raycaster()
    this.raycaster.far = REACH

    const outlineGeometry = new THREE.EdgesGeometry(new THREE.BoxGeometry(1.006, 1.006, 1.006))
    this.highlight = new THREE.LineSegments(
      outlineGeometry,
      new THREE.LineBasicMaterial({ color: 0x101510, transparent: true, opacity: 0.72, depthTest: true }),
    )
    this.highlight.renderOrder = 4
    this.highlight.visible = false
    scene.add(this.highlight)

    this.crackTextures = makeCrackTextures()
    this.crackMaterial = new THREE.MeshBasicMaterial({
      map: this.crackTextures[0],
      transparent: true,
      opacity: 0.9,
      depthWrite: false,
      polygonOffset: true,
      polygonOffsetFactor: -2,
      polygonOffsetUnits: -2,
    })
    this.crackMesh = new THREE.Mesh(new THREE.BoxGeometry(1.008, 1.008, 1.008), this.crackMaterial)
    this.crackMesh.visible = false
    this.crackMesh.renderOrder = 5
    scene.add(this.crackMesh)
  }

  setSpawn(spawn) {
    this.spawn.copy(spawn)
    this.teleport(spawn)
  }

  teleport(position) {
    this.position.copy(position)
    this.velocity.set(0, 0, 0)
    this.peakY = position.y
    this.airTime = 0
    this.onGround = false
  }

  getEyePosition() {
    return this.tmp.set(this.position.x, this.position.y + EYE_HEIGHT, this.position.z)
  }

  look(dx, dy, sensitivity = 0.0022) {
    this.yaw -= dx * sensitivity
    this.pitch -= dy * sensitivity
    const limit = Math.PI / 2 - 0.015
    this.pitch = Math.max(-limit, Math.min(limit, this.pitch))
  }

  setTouchMove(x, y) {
    this.input.touchRight = x
    this.input.touchForward = y
  }

  collides(position) {
    const eps = 0.0005
    const half = PLAYER_WIDTH / 2
    const minX = Math.floor(position.x - half + eps)
    const maxX = Math.floor(position.x + half - eps)
    const minY = Math.floor(position.y + eps)
    const maxY = Math.floor(position.y + PLAYER_HEIGHT - eps)
    const minZ = Math.floor(position.z - half + eps)
    const maxZ = Math.floor(position.z + half - eps)
    for (let y = minY; y <= maxY; y++) {
      for (let z = minZ; z <= maxZ; z++) {
        for (let x = minX; x <= maxX; x++) {
          if (this.world.isSolid(x, y, z)) return true
        }
      }
    }
    return false
  }

  moveAxis(axis, amount) {
    if (amount === 0) return false
    const old = this.position[axis]
    this.position[axis] += amount
    if (this.collides(this.position)) {
      this.position[axis] = old
      return true
    }
    return false
  }

  toggleFly() {
    this.flying = !this.flying
    this.velocity.y = 0
    return this.flying
  }

  takeDamage(amount, cause = 'fall') {
    if (this.dead || amount <= 0) return
    this.health = Math.max(0, this.health - amount)
    this.lastDamage = performance.now() / 1000
    this.shake = Math.min(1, this.shake + 0.35 + amount * 0.07)
    this.audio.hurt()
    if (this.onDamage) this.onDamage(amount, cause)
    if (this.onHealthChanged) this.onHealthChanged(this.health)
    if (this.health <= 0) {
      this.dead = true
      this.velocity.set(0, 0, 0)
      if (this.onDeath) this.onDeath()
    }
  }

  respawn() {
    this.health = this.maxHealth
    this.oxygen = 300
    this.dead = false
    this.lastDamage = -99
    this.teleport(this.world.findSpawn())
    if (this.onHealthChanged) this.onHealthChanged(this.health)
  }

  update(dt) {
    const now = performance.now() / 1000
    if (this.dead) {
      this.highlight.visible = false
      this.crackMesh.visible = false
      this.updateCamera(dt)
      return
    }

    const feetBlock = this.world.getBlock(Math.floor(this.position.x), Math.floor(this.position.y + 0.15), Math.floor(this.position.z))
    const chestBlock = this.world.getBlock(Math.floor(this.position.x), Math.floor(this.position.y + 1.35), Math.floor(this.position.z))
    const headBlock = this.world.getBlock(Math.floor(this.position.x), Math.floor(this.position.y + 1.68), Math.floor(this.position.z))
    const wasInWater = this.inWater
    this.inWater = feetBlock === BLOCK.WATER || chestBlock === BLOCK.WATER
    this.headInWater = headBlock === BLOCK.WATER
    if (this.inWater && !wasInWater) {
      if (this.velocity.y < -4) this.effects.splash(this.position.x, this.position.y + 0.1, this.position.z)
      this.audio.splash()
      this.airTime = 0
      this.peakY = this.position.y
    }

    let forwardInput = (this.input.forward ? 1 : 0) - (this.input.back ? 1 : 0) + this.input.touchForward
    let rightInput = (this.input.right ? 1 : 0) - (this.input.left ? 1 : 0) + this.input.touchRight
    forwardInput = Math.max(-1, Math.min(1, forwardInput))
    rightInput = Math.max(-1, Math.min(1, rightInput))
    const inputLength = Math.hypot(forwardInput, rightInput)
    if (inputLength > 1) {
      forwardInput /= inputLength
      rightInput /= inputLength
    }

    const sin = Math.sin(this.yaw)
    const cos = Math.cos(this.yaw)
    let wishX = forwardInput * -sin + rightInput * cos
    let wishZ = forwardInput * -cos + rightInput * -sin
    const wishLength = Math.hypot(wishX, wishZ)
    if (wishLength > 1) {
      wishX /= wishLength
      wishZ /= wishLength
    }

    const sprinting = this.input.sprint && forwardInput > 0.15 && !this.inWater && !this.flying
    const targetSpeed = this.flying ? FLY_SPEED : this.inWater ? 3.25 : sprinting ? SPRINT_SPEED : WALK_SPEED
    const accel = this.flying ? 8 : this.inWater ? 4.2 : this.onGround ? 15 : 5.5
    const blend = 1 - Math.exp(-accel * dt)
    this.velocity.x += (wishX * targetSpeed - this.velocity.x) * blend
    this.velocity.z += (wishZ * targetSpeed - this.velocity.z) * blend

    if (this.flying) {
      const vertical = (this.input.jump ? 1 : 0) - (this.input.descend ? 1 : 0)
      this.velocity.y += (vertical * FLY_SPEED - this.velocity.y) * (1 - Math.exp(-10 * dt))
      this.onGround = false
    } else if (this.inWater) {
      if (this.input.jump) this.velocity.y = Math.min(4.2, this.velocity.y + 22 * dt)
      else this.velocity.y -= 6.5 * dt
      this.velocity.y = Math.max(this.velocity.y, -3.6)
      this.onGround = false
    } else {
      if (this.input.jump && this.onGround) {
        this.velocity.y = 9.15
        this.onGround = false
        this.audio.jump()
        this.peakY = this.position.y
        this.airTime = 0
      }
      this.velocity.y -= GRAVITY * dt
      this.velocity.y = Math.max(this.velocity.y, -38)
    }

    const wasOnGround = this.onGround
    if (this.moveAxis('x', this.velocity.x * dt)) this.velocity.x = 0
    if (this.moveAxis('z', this.velocity.z * dt)) this.velocity.z = 0
    const hitVertical = this.moveAxis('y', this.velocity.y * dt)
    if (hitVertical) {
      if (this.velocity.y < 0) this.onGround = true
      this.velocity.y = 0
    } else if (!this.inWater && !this.flying) {
      this.onGround = false
    }

    if (this.onGround) {
      if (!wasOnGround) {
        if (this.airTime > 0.15 && this.peakY - this.position.y > 3.5 && !this.inWater) {
          const damage = Math.floor(this.peakY - this.position.y - 3)
          if (damage > 0) this.takeDamage(damage, 'fall')
        }
        this.airTime = 0
        this.peakY = this.position.y
      }
    } else {
      this.airTime += dt
      this.peakY = Math.max(this.peakY, this.position.y)
    }

    if (this.position.y < -8) {
      this.takeDamage(99, 'void')
      this.teleport(this.world.findSpawn())
    }

    if (this.headInWater) {
      this.oxygen = Math.max(0, this.oxygen - dt * 8)
      if (this.oxygen <= 0) {
        this.drownTimer += dt
        if (this.drownTimer > 1) {
          this.drownTimer = 0
          this.takeDamage(2, 'drown')
        }
      }
    } else {
      this.oxygen = Math.min(300, this.oxygen + dt * 35)
      this.drownTimer = 0
    }

    if (now - this.lastDamage > 6 && this.health > 0 && this.health < this.maxHealth) {
      this.health = Math.min(this.maxHealth, this.health + dt * 0.65)
      if (this.onHealthChanged) this.onHealthChanged(this.health)
      this.lastDamage = now - 5.2
    }

    const horizontalSpeed = Math.hypot(this.velocity.x, this.velocity.z)
    if (this.onGround && horizontalSpeed > 0.25) {
      this.walkPhase += dt * horizontalSpeed * 1.72
      this.bob = Math.sin(this.walkPhase * 2) * Math.min(0.045, horizontalSpeed * 0.007)
      this.roll = Math.sin(this.walkPhase) * Math.min(0.007, horizontalSpeed * 0.0011)
      this.stepDistance += horizontalSpeed * dt
      if (this.stepDistance > (sprinting ? 1.9 : 1.55)) {
        this.stepDistance = 0
        const under = this.world.topBlock(this.position.x, this.position.z)
        const name = BLOCKS[under]?.name || 'grass'
        this.audio.step(/sand/i.test(name) ? 'sand' : /snow/i.test(name) ? 'snow' : /stone|cobble|brick/i.test(name) ? 'stone' : 'grass')
        if (this.onFootstep) this.onFootstep()
      }
    } else {
      this.bob += (0 - this.bob) * Math.min(1, dt * 8)
      this.roll += (0 - this.roll) * Math.min(1, dt * 8)
    }

    this.shake = Math.max(0, this.shake - dt * 1.7)
    this.updateCamera(dt)
  }

  updateCamera(dt) {
    const targetFov = this.input.sprint && !this.inWater ? 75 : 70
    this.fov += (targetFov - this.fov) * Math.min(1, dt * 8)
    this.camera.fov = this.fov
    this.camera.updateProjectionMatrix()
    const shakeX = (Math.random() - 0.5) * this.shake * 0.06
    const shakeY = (Math.random() - 0.5) * this.shake * 0.06
    this.camera.position.set(
      this.position.x + shakeX,
      this.position.y + EYE_HEIGHT + this.bob + shakeY,
      this.position.z,
    )
    this.camera.rotation.set(this.pitch, this.yaw, this.roll, 'YXZ')
    this.camera.updateMatrixWorld()
  }

  updateTarget(active = true) {
    if (!active || this.dead) {
      this.highlight.visible = false
      this.crackMesh.visible = false
      this.target = null
      return null
    }
    this.raycaster.setFromCamera({ x: 0, y: 0 }, this.camera)
    const hits = this.raycaster.intersectObjects(this.world.chunkMeshes, false)
    let hit = null
    for (const candidate of hits) {
      if (candidate.object.userData.slot === 'mesh') {
        hit = candidate
        break
      }
    }
    if (!hit) {
      this.highlight.visible = false
      this.crackMesh.visible = false
      this.target = null
      return null
    }
    const normal = hit.face.normal
    const blockX = Math.floor(hit.point.x - normal.x * 0.5)
    const blockY = Math.floor(hit.point.y - normal.y * 0.5)
    const blockZ = Math.floor(hit.point.z - normal.z * 0.5)
    const blockId = this.world.getBlock(blockX, blockY, blockZ)
    const signature = `${blockX},${blockY},${blockZ}`
    if (signature !== this.miningKey) {
      this.miningKey = signature
      this.miningProgress = 0
    }
    this.target = {
      x: blockX, y: blockY, z: blockZ, block: blockId,
      nx: normal.x, ny: normal.y, nz: normal.z,
      signature,
    }
    this.highlight.position.set(blockX + 0.5, blockY + 0.5, blockZ + 0.5)
    this.highlight.visible = true
    return this.target
  }

  updateMining(dt, active, holding, onBreak) {
    if (!active || this.dead) {
      this.crackMesh.visible = false
      return
    }
    const target = this.updateTarget(active)
    if (!target || !holding) {
      this.miningProgress = 0
      this.crackMesh.visible = false
      return
    }
    const definition = BLOCKS[target.block]
    const hardness = BREAK_TIME[target.block] || 0.35
    this.miningProgress += dt / hardness
    const stage = Math.min(5, Math.floor(this.miningProgress * 6))
    this.crackMaterial.map = this.crackTextures[stage]
    this.crackMaterial.needsUpdate = true
    this.crackMesh.position.set(target.x + 0.5, target.y + 0.5, target.z + 0.5)
    this.crackMesh.visible = this.miningProgress > 0.018
    if (this.miningProgress >= 1) {
      this.world.setBlock(target.x, target.y, target.z, BLOCK.AIR)
      this.effects.burst(target.x, target.y, target.z, target.block, 16)
      this.audio.breakBlock(definition?.name)
      this.miningProgress = 0
      this.crackMesh.visible = false
      this.miningKey = ''
      if (onBreak) onBreak(target)
    }
  }

  placeBlock(blockId, active, onPlace) {
    if (!active || this.dead) return false
    const target = this.target
    if (!target) return false
    const x = target.x + target.nx
    const y = target.y + target.ny
    const z = target.z + target.nz
    if (y <= 0 || y >= 64) return false
    const existing = this.world.getBlock(x, y, z)
    if (BLOCKS[existing].solid) return false
    if (this.intersectsBlock(x, y, z)) return false
    this.world.setBlock(x, y, z, blockId)
    this.effects.burst(x, y, z, blockId, 5, 1.2)
    this.audio.placeBlock()
    if (onPlace) onPlace({ x, y, z, block: blockId })
    return true
  }

  intersectsBlock(x, y, z) {
    const half = PLAYER_WIDTH / 2 + 0.001
    return (
      this.position.x + half > x && this.position.x - half < x + 1 &&
      this.position.y + PLAYER_HEIGHT > y && this.position.y < y + 1 &&
      this.position.z + half > z && this.position.z - half < z + 1
    )
  }

  isUnderwater() {
    return this.headInWater
  }
}

:root {
  --ink: #f6fbf4;
  --muted: rgba(226, 240, 235, 0.68);
  --panel: rgba(10, 19, 18, 0.66);
  --panel-solid: rgba(12, 21, 20, 0.93);
  --line: rgba(237, 255, 247, 0.16);
  --green: #72c04a;
  --green-deep: #39752b;
  --gold: #ffda68;
  --danger: #ff5c4d;
  --safe: 18px;
  font-synthesis: none;
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #8ec6e8;
  color: var(--ink);
  font-family: "Trebuchet MS", "Gill Sans", "Segoe UI", sans-serif;
  -webkit-tap-highlight-color: transparent;
}

body {
  user-select: none;
  -webkit-user-select: none;
}

canvas#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  touch-action: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  cursor: pointer;
}

kbd {
  display: inline-flex;
  min-width: 22px;
  height: 22px;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-bottom-color: rgba(0, 0, 0, 0.55);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.09);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12), 0 2px 0 rgba(0, 0, 0, 0.18);
  color: #f2f8f1;
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  line-height: 1;
}

.is-hidden {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

/* ---------------------------------------------------------------- loading */
.loading-screen {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at 50% 35%, rgba(142, 199, 216, 0.34), transparent 45%),
    linear-gradient(155deg, #0b171a 0%, #13282a 55%, #1c312b 100%);
  transition: opacity 0.6s ease, visibility 0s linear 0.6s;
}

.loading-screen.is-hidden {
  opacity: 0;
  visibility: hidden;
}

.loading-inner {
  width: min(360px, 82vw);
  text-align: center;
  animation: float-in 0.6s ease both;
}

.loading-cube {
  position: relative;
  width: 58px;
  height: 58px;
  margin: 0 auto 26px;
  animation: cube-hop 1.6s ease-in-out infinite;
}

.loading-cube span {
  position: absolute;
  inset: 0;
  border-radius: 3px;
  background: linear-gradient(140deg, #9ed769, #62a43b 45%, #497d2d);
  border: 2px solid rgba(230, 255, 213, 0.3);
  box-shadow: inset -10px -12px 0 rgba(24, 65, 22, 0.18);
}

.loading-cube span:nth-child(2) {
  transform: translate(8px, 8px) scale(0.88);
  filter: brightness(0.68);
  z-index: -1;
}

.loading-cube span:nth-child(3) {
  transform: translate(16px, 16px) scale(0.75);
  filter: brightness(0.42);
  z-index: -2;
}

.loading-inner h2 {
  margin: 0 0 6px;
  font-size: 15px;
  letter-spacing: 0.34em;
  color: #e4f4df;
}

.loading-inner p {
  margin: 0 0 22px;
  font-size: 12px;
  letter-spacing: 0.08em;
  color: rgba(220, 240, 232, 0.55);
}

.loading-track {
  height: 3px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.09);
}

.loading-bar {
  width: 12%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #5c9e42, #b2e47d);
  transition: width 0.28s ease;
  box-shadow: 0 0 14px rgba(166, 229, 111, 0.45);
}

@keyframes cube-hop {
  0%, 100% { transform: translateY(0) rotate(-2deg); }
  45% { transform: translateY(-8px) rotate(2deg); }
}

@keyframes float-in {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ---------------------------------------------------------------- screens */
.screen {
  position: fixed;
  inset: 0;
  z-index: 20;
  transition: opacity 0.38s ease, visibility 0s linear 0.38s;
}

/* ---------------------------------------------------------------- title */
.title-screen {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 24px;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 32%, rgba(4, 16, 13, 0.02) 0%, rgba(4, 13, 12, 0.16) 44%, rgba(2, 8, 9, 0.72) 100%),
    linear-gradient(180deg, rgba(5, 15, 20, 0.3) 0%, rgba(5, 15, 20, 0.02) 25%, rgba(2, 8, 9, 0.08) 55%, rgba(2, 8, 9, 0.74) 100%);
}

.menu-grain {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.12;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 140 140' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.35'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}

.menu-content {
  position: relative;
  z-index: 1;
  width: min(920px, calc(100vw - 48px));
  padding: 0 16px;
  text-align: center;
  animation: menu-rise 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes menu-rise {
  from { opacity: 0; transform: translateY(26px); }
  to { opacity: 1; transform: translateY(0); }
}

.kicker {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 16px;
  padding: 7px 14px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 99px;
  background: rgba(7, 16, 16, 0.34);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.15);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.22em;
  color: rgba(232, 248, 238, 0.76);
  backdrop-filter: blur(10px);
}

.live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #90de63;
  box-shadow: 0 0 10px #8edf62;
  animation: live-pulse 2.4s ease-in-out infinite;
}

@keyframes live-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.55; transform: scale(0.84); }
}

.menu-hero {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(8px, 3vw, 34px);
}

.menu-block {
  width: clamp(74px, 9vw, 118px);
  height: auto;
  image-rendering: pixelated;
  filter: drop-shadow(0 22px 26px rgba(0, 0, 0, 0.4));
  animation: menu-block-float 5s ease-in-out infinite;
  transform-origin: 50% 70%;
}

@keyframes menu-block-float {
  0%, 100% { transform: translateY(2px) rotate(-3deg); }
  50% { transform: translateY(-10px) rotate(3deg); }
}

.title-wrap {
  position: relative;
  text-align: left;
}

.logo {
  position: relative;
  display: flex;
  align-items: flex-start;
  margin: 0;
  line-height: 0.86;
  filter: drop-shadow(0 22px 34px rgba(0, 0, 0, 0.3));
}

.logo-main {
  font-family: Impact, "Arial Black", "Franklin Gothic Heavy", sans-serif;
  font-size: clamp(58px, 8.7vw, 118px);
  font-weight: 900;
  letter-spacing: -0.045em;
  color: #f8fbf0;
  -webkit-text-stroke: clamp(2px, 0.36vw, 5px) #23331f;
  text-shadow:
    0 4px 0 #7b995f,
    0 8px 0 #4d673b,
    0 12px 0 #2e4527,
    0 17px 0 rgba(12, 23, 13, 0.55),
    0 26px 50px rgba(0, 0, 0, 0.38);
}

.logo-badge {
  position: relative;
  top: clamp(2px, 0.8vw, 9px);
  margin-left: 10px;
  padding: 3px 7px 4px;
  border: 2px solid #263a20;
  border-radius: 5px;
  background: linear-gradient(150deg, #ffe880, #e6b63e 62%, #b78423);
  box-shadow: 0 4px 0 #5b4014, 0 12px 24px rgba(0, 0, 0, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.4);
  color: #2b2710;
  font-family: "Arial Black", sans-serif;
  font-size: clamp(14px, 1.6vw, 21px);
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1;
  transform: rotate(4deg);
}

.tagline {
  margin: clamp(14px, 2vw, 25px) 0 0 2px;
  color: rgba(236, 248, 238, 0.8);
  font-size: clamp(13px, 1.25vw, 16px);
  font-weight: 500;
  letter-spacing: 0.015em;
  line-height: 1.65;
  text-shadow: 0 2px 14px rgba(0, 0, 0, 0.55);
}

.menu-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-top: clamp(20px, 3vw, 32px);
}

.primary-button {
  position: relative;
  overflow: hidden;
  min-width: 238px;
  padding: 16px 32px;
  border: 2px solid #24431e;
  border-radius: 5px;
  background: linear-gradient(180deg, #8bdc64 0%, #67b947 44%, #4b9634 100%);
  box-shadow:
    0 5px 0 #2c6021,
    0 8px 0 rgba(20, 45, 16, 0.55),
    0 20px 42px rgba(0, 0, 0, 0.35),
    inset 0 2px 0 rgba(255, 255, 255, 0.37),
    inset 0 -3px 0 rgba(22, 72, 20, 0.24);
  color: #fafff4;
  font-family: "Arial Black", Impact, sans-serif;
  font-size: 17px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-shadow: 0 2px 0 rgba(27, 68, 24, 0.8), 0 0 18px rgba(255, 255, 255, 0.18);
  transition: transform 0.12s ease, box-shadow 0.12s ease, filter 0.12s ease;
}

.primary-button:hover {
  filter: brightness(1.08) saturate(1.04);
  transform: translateY(-2px);
  box-shadow:
    0 7px 0 #2c6021,
    0 10px 0 rgba(20, 45, 16, 0.55),
    0 24px 48px rgba(0, 0, 0, 0.4),
    inset 0 2px 0 rgba(255, 255, 255, 0.42),
    inset 0 -3px 0 rgba(22, 72, 20, 0.24);
}

.primary-button:active {
  transform: translateY(4px);
  box-shadow:
    0 1px 0 #2c6021,
    0 3px 0 rgba(20, 45, 16, 0.55),
    0 10px 20px rgba(0, 0, 0, 0.3),
    inset 0 2px 0 rgba(255, 255, 255, 0.25);
}

.primary-button.compact {
  min-width: 190px;
  padding: 13px 25px;
  font-size: 14px;
}

.button-sheen {
  position: absolute;
  top: -60%;
  left: -20%;
  width: 24%;
  height: 220%;
  transform: rotate(20deg);
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.35), transparent);
  animation: sheen 4.8s ease-in-out infinite;
}

@keyframes sheen {
  0%, 62% { left: -30%; }
  82%, 100% { left: 120%; }
}

.menu-note {
  margin: 14px 0 0;
  color: rgba(226, 241, 233, 0.55);
  font-size: 11px;
  letter-spacing: 0.04em;
}

.menu-note kbd {
  height: 18px;
  min-width: 26px;
  margin: 0 2px;
  font-size: 9px;
}

.feature-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  width: min(720px, 100%);
  margin: clamp(22px, 3vw, 34px) auto 0;
}

.feature {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 7px;
  background: linear-gradient(155deg, rgba(19, 36, 31, 0.54), rgba(7, 16, 16, 0.4));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.07), 0 10px 30px rgba(0, 0, 0, 0.12);
  text-align: left;
  backdrop-filter: blur(8px);
}

.feature-icon {
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  flex: 0 0 auto;
  border-radius: 5px;
  background: rgba(142, 214, 99, 0.13);
  box-shadow: inset 0 0 0 1px rgba(166, 230, 123, 0.15);
  color: #acd98b;
  font-size: 13px;
}

.feature b {
  display: block;
  margin-bottom: 2px;
  font-size: 11px;
  letter-spacing: 0.02em;
  color: rgba(247, 252, 244, 0.94);
}

.feature small {
  display: block;
  font-size: 9.5px;
  letter-spacing: 0.02em;
  color: rgba(220, 236, 228, 0.5);
}

.menu-shortcuts {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 20px;
  color: rgba(230, 243, 235, 0.55);
  font-size: 10px;
  letter-spacing: 0.06em;
}

.menu-shortcuts span {
  display: flex;
  align-items: center;
  gap: 3px;
}

.menu-footer {
  position: absolute;
  bottom: 19px;
  left: 0;
  right: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: clamp(20px, 5vw, 64px);
  padding: 0 var(--safe);
  color: rgba(220, 235, 229, 0.38);
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 9px;
  letter-spacing: 0.1em;
}

.menu-footer b {
  color: rgba(238, 248, 241, 0.68);
  font-weight: 500;
}

.footer-mark {
  letter-spacing: 0.14em;
}

.mute-btn {
  padding: 5px 9px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 4px;
  background: transparent;
  color: rgba(228, 241, 233, 0.55);
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 8px;
  letter-spacing: 0.12em;
}

.mute-btn:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}

/* ---------------------------------------------------------------- pause */
.pause-screen {
  display: grid;
  place-items: center;
  background: rgba(3, 9, 10, 0.45);
  backdrop-filter: blur(9px) saturate(0.75);
}

.pause-panel {
  width: min(440px, calc(100vw - 40px));
  padding: 34px 34px 28px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 10px;
  background:
    linear-gradient(150deg, rgba(26, 43, 38, 0.92), rgba(7, 15, 15, 0.94));
  box-shadow: 0 32px 90px rgba(0, 0, 0, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  text-align: center;
}

.pause-kicker,
.death-kicker {
  margin-bottom: 10px;
  color: #9eda76;
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 9px;
  letter-spacing: 0.28em;
}

.pause-panel h2 {
  margin: 0 0 8px;
  font-family: "Arial Black", Impact, sans-serif;
  font-size: 34px;
  letter-spacing: -0.03em;
}

.pause-panel > p {
  margin: 0 0 22px;
  color: var(--muted);
  font-size: 12px;
}

.pause-links {
  display: flex;
  justify-content: center;
  gap: 22px;
  margin-top: 20px;
}

.text-button {
  padding: 0;
  border-bottom: 1px solid transparent;
  background: transparent;
  color: rgba(229, 242, 234, 0.58);
  font-size: 11px;
}

.text-button:hover {
  border-color: rgba(255, 255, 255, 0.4);
  color: #fff;
}

.pause-controls {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px 15px;
  margin-top: 26px;
  padding-top: 21px;
  border-top: 1px solid rgba(255, 255, 255, 0.09);
  color: rgba(222, 238, 229, 0.48);
  font-size: 9.5px;
}

.pause-controls span {
  display: flex;
  align-items: center;
  gap: 5px;
}

/* ---------------------------------------------------------------- hud */
.hud {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.hud-top {
  position: absolute;
  top: max(var(--safe), env(safe-area-inset-top));
  left: max(var(--safe), env(safe-area-inset-left));
  right: max(var(--safe), env(safe-area-inset-right));
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}

.brand-chip {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 12px 7px 8px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 6px;
  background: rgba(8, 18, 17, 0.46);
  box-shadow: 0 5px 18px rgba(0, 0, 0, 0.13), inset 0 1px 0 rgba(255, 255, 255, 0.07);
  color: rgba(245, 250, 242, 0.9);
  font-family: "Arial Black", Impact, sans-serif;
  font-size: 10px;
  letter-spacing: 0.09em;
  backdrop-filter: blur(8px);
}

.brand-chip b {
  color: var(--gold);
}

#brandBlock {
  width: 27px;
  height: 27px;
  image-rendering: pixelated;
}

.status-cluster {
  display: flex;
  align-items: stretch;
  gap: 6px;
}

.status-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 32px;
  padding: 5px 9px;
  border: 1px solid rgba(255, 255, 255, 0.11);
  border-radius: 5px;
  background: rgba(8, 18, 17, 0.42);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 10px;
  backdrop-filter: blur(8px);
}

.chip-label {
  color: rgba(212, 234, 220, 0.42);
  font-size: 8px;
  letter-spacing: 0.12em;
}

.status-chip b {
  color: rgba(239, 248, 243, 0.8);
  font-weight: 500;
  letter-spacing: 0.02em;
}

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 20px;
  height: 20px;
  transform: translate(-50%, -50%);
  opacity: 0.82;
  filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.75));
  mix-blend-mode: difference;
}

.crosshair span {
  position: absolute;
