}

.crosshair span:first-child {
  left: 9px;
  top: 2px;
  width: 2px;
  height: 16px;
}

.crosshair span:last-child {
  left: 2px;
  top: 9px;
  width: 16px;
  height: 2px;
}

.vignette {
  position: absolute;
