  background: radial-gradient(ellipse at center, transparent 48%, rgba(3, 10, 8, 0.24) 100%);
}

.underwater-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background:
    radial-gradient(ellipse at center, rgba(19, 99, 142, 0.16), rgba(4, 40, 64, 0.58)),
