}

.heart {
  font-family: Georgia, serif;
  font-size: 17px;
  line-height: 1;
  color: #ff5547;
  text-shadow: 0 0 1px #501212, 0 1px 0 #49100c;
}

.heart.empty {
  color: rgba(12, 20, 18, 0.48);
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.08);
}

.heart.half {
  background: linear-gradient(90deg, #ff5547 50%, rgba(12, 20, 18, 0.48) 50%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: none;
}

.mode-chip {
  margin-left: auto;
  padding: 3px 7px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 3px;
  background: rgba(7, 15, 14, 0.46);
  color: rgba(222, 240, 231, 0.52);
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 8px;
  letter-spacing: 0.15em;
  backdrop-filter: blur(6px);
}

.mode-chip.flying {
  border-color: rgba(124, 209, 255, 0.32);
  color: #9bdcff;
}

.selected-block {
  min-height: 16px;
  margin-bottom: 5px;
  color: rgba(248, 251, 241, 0.9);
  font-family: "Arial Black", Impact, sans-serif;
  font-size: 11px;
  letter-spacing: 0.1em;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.8);
  text-transform: uppercase;
  transition: opacity 0.22s ease, transform 0.22s ease;
}

.selected-block.pop {
  opacity: 0;
  transform: translateY(-3px);
}

.hotbar {
  display: flex;
  gap: 3px;
  padding: 5px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 6px;
  background: rgba(8, 15, 14, 0.55);
  box-shadow:
    0 8px 26px rgba(0, 0, 0, 0.33),
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    inset 0 0 0 1px rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(10px) saturate(0.9);
}

.hotbar-slot {
  position: relative;
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.045);
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.28);
  transition: transform 0.12s ease, background 0.12s ease, border-color 0.12s ease;
}

.hotbar-slot canvas {
  width: 38px;
  height: 38px;
  image-rendering: pixelated;
  filter: drop-shadow(0 4px 4px rgba(0, 0, 0, 0.32));
}

.hotbar-slot .slot-key {
  position: absolute;
  top: 2px;
  left: 4px;
  color: rgba(232, 245, 237, 0.38);
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 7px;
}

.hotbar-slot::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 2px;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0);
  transition: box-shadow 0.12s ease;
}

.hotbar-slot.selected {
  background: rgba(238, 246, 219, 0.14);
  border-color: rgba(255, 246, 197, 0.78);
  transform: translateY(-3px);
  box-shadow: 0 5px 14px rgba(0, 0, 0, 0.3), inset 0 0 16px rgba(255, 240, 160, 0.1);
}

.hotbar-slot.selected::after {
  box-shadow: inset 0 0 0 1px rgba(255, 247, 198, 0.6), 0 0 13px rgba(255, 223, 101, 0.18);
}

.desktop-hint {
  display: flex;
  gap: 14px;
  margin-top: 8px;
  padding: 5px 10px;
  border-radius: 4px;
  background: rgba(7, 15, 14, 0.28);
  color: rgba(225, 239, 231, 0.52);
  font-size: 9px;
  letter-spacing: 0.025em;
  opacity: 0;
  animation: hint-in 0.6s 2s ease forwards;
  backdrop-filter: blur(4px);
}

.desktop-hint span {
  display: flex;
  align-items: center;
  gap: 4px;
}

.desktop-hint kbd {
  height: 17px;
  min-width: 19px;
  font-size: 8px;
}

@keyframes hint-in {
  to { opacity: 0.8; }
}

.oxygen {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 6px;
  padding: 4px 8px;
  border: 1px solid rgba(140, 220, 255, 0.2);
  border-radius: 4px;
  background: rgba(4, 20, 29, 0.48);
  color: #a8e2ff;
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 8px;
  letter-spacing: 0.13em;
  backdrop-filter: blur(6px);
}

.oxygen-pips {
  display: flex;
  gap: 2px;
}

.oxygen-pip {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #72c9ee;
  box-shadow: 0 0 5px rgba(111, 203, 240, 0.45);
}

.oxygen-pip.off {
  background: rgba(255, 255, 255, 0.12);
  box-shadow: none;
}

.toast {
  position: absolute;
  top: 16%;
  left: 50%;
  padding: 9px 16px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 5px;
  background: rgba(7, 16, 15, 0.78);
  box-shadow: 0 10px 32px rgba(0, 0, 0, 0.32);
  color: rgba(245, 251, 245, 0.92);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.03em;
  opacity: 0;
  transform: translate(-50%, -8px);
  transition: opacity 0.22s ease, transform 0.22s ease;
  backdrop-filter: blur(8px);
  white-space: nowrap;
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------------------------------------------------------------- death */
.death-screen {
  display: grid;
  place-items: center;
  z-index: 35;
  background: rgba(27, 8, 7, 0.42);
  backdrop-filter: grayscale(0.75) blur(2px);
}

.death-vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(62, 8, 7, 0.05) 30%, rgba(50, 4, 4, 0.75) 100%);
}

.death-content {
  position: relative;
  text-align: center;
  animation: death-in 0.75s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes death-in {
  from { opacity: 0; transform: scale(1.06); }
  to { opacity: 1; transform: scale(1); }
}

.death-kicker {
  color: #ef8e74;
}

.death-content h2 {
  margin: 0 0 10px;
  color: #f7e8e3;
  font-family: "Arial Black", Impact, sans-serif;
  font-size: clamp(52px, 8vw, 90px);
  letter-spacing: -0.035em;
  text-shadow: 0 4px 0 #6b2822, 0 16px 44px rgba(0, 0, 0, 0.5);
}

.death-content p {
  margin: 0 0 26px;
  color: rgba(248, 230, 224, 0.7);
  font-size: 13px;
}

.death-note {
  display: block;
  margin-top: 19px;
  color: rgba(247, 226, 218, 0.37);
  font-size: 10px;
}

/* ---------------------------------------------------------------- mobile */
.mobile-controls {
  position: fixed;
  inset: 0;
  z-index: 12;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.joystick {
  position: absolute;
  left: max(24px, env(safe-area-inset-left));
  bottom: max(105px, calc(env(safe-area-inset-bottom) + 100px));
  width: 122px;
  height: 122px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 50%;
  background: rgba(6, 16, 14, 0.24);
  box-shadow: inset 0 0 40px rgba(0, 0, 0, 0.16);
  backdrop-filter: blur(4px);
  pointer-events: auto;
  touch-action: none;
}

.joystick::before {
  content: "";
  position: absolute;
  inset: 25%;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 50%;
}

.joystick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 50px;
  height: 50px;
  margin: -25px 0 0 -25px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 50%;
  background: rgba(238, 247, 231, 0.2);
  box-shadow: 0 7px 22px rgba(0, 0, 0, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.2);
}

.touch-actions {
  position: absolute;
  right: max(22px, env(safe-area-inset-right));
  bottom: max(110px, calc(env(safe-area-inset-bottom) + 105px));
  display: grid;
  grid-template-columns: repeat(2, 68px);
  gap: 10px;
  pointer-events: auto;
}

.touch-button {
  display: grid;
  place-items: center;
  width: 68px;
  height: 68px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 50%;
  background: rgba(7, 17, 15, 0.3);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.14), 0 8px 20px rgba(0, 0, 0, 0.16);
  color: rgba(247, 251, 243, 0.85);
  font-family: "Arial Black", Impact, sans-serif;
  font-size: 9px;
  letter-spacing: 0.09em;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.65);
  backdrop-filter: blur(6px);
  touch-action: none;
}

.touch-button:active,
.touch-button.pressed {
  background: rgba(235, 247, 224, 0.23);
  transform: scale(0.95);
}

.touch-button.jump {
  grid-column: 2 / 3;
  grid-row: 1 / 2;
}

.touch-button.place {
  width: 58px;
  height: 58px;
  margin: 5px 0 0 10px;
  grid-column: 1 / 2;
  grid-row: 2 / 3;
  border-color: rgba(158, 223, 255, 0.3);
}

.touch-button.break {
  width: 82px;
  height: 82px;
  margin: 0 0 0 -7px;
  grid-column: 2 / 3;
  grid-row: 2 / 3;
  border-color: rgba(255, 218, 104, 0.38);
  background: rgba(44, 36, 11, 0.34);
}

.touch-look-hint {
  position: absolute;
  top: 24%;
  right: 19px;
  padding: 5px 8px;
  border-radius: 3px;
  background: rgba(5, 14, 13, 0.22);
  color: rgba(234, 245, 237, 0.35);
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 8px;
  letter-spacing: 0.1em;
  animation: hint-fade 4s 1.5s both;
}

@keyframes hint-fade {
  0%, 70% { opacity: 0.9; }
  100% { opacity: 0; }
}

@media (pointer: coarse) {
  .desktop-hint {
    display: none;
  }
  .crosshair {
    opacity: 0.62;
  }
  .hud-bottom {
    bottom: max(8px, env(safe-area-inset-bottom));
  }
  .selected-block {
    font-size: 9px;
    margin-bottom: 3px;
  }
}

@media (max-width: 740px) {
  :root {
    --safe: 10px;
  }

  .menu-content {
    width: calc(100vw - 20px);
    padding: 0 8px;
  }

  .menu-hero {
    gap: 4px;
    flex-direction: column;
  }

  .menu-block {
    width: 62px;
    margin-bottom: -6px;
  }

  .title-wrap {
    text-align: center;
  }

  .logo {
    justify-content: center;
  }

  .logo-main {
    font-size: clamp(48px, 14.6vw, 74px);
  }

  .tagline {
    margin-top: 13px;
    font-size: 12px;
  }

  .kicker {
    margin-bottom: 12px;
    font-size: 8px;
    letter-spacing: 0.17em;
  }

  .feature-row {
    display: none;
  }

  .menu-actions {
    margin-top: 22px;
  }

  .primary-button {
    min-width: 220px;
    padding: 15px 26px;
    font-size: 15px;
  }

  .menu-shortcuts {
    display: none;
  }

  .menu-footer {
    bottom: max(12px, env(safe-area-inset-bottom));
    justify-content: space-between;
    gap: 8px;
    font-size: 7px;
  }

  .footer-mark {
    display: none;
  }

  .menu-note {
    max-width: 250px;
    font-size: 9.5px;
  }

  .status-cluster {
    gap: 4px;
  }

  .status-chip {
    padding: 4px 7px;
    min-height: 28px;
    font-size: 9px;
  }

  .brand-chip {
    padding: 5px 9px 5px 6px;
    font-size: 8px;
  }

  #brandBlock {
    width: 22px;
    height: 22px;
  }

  .hud-bottom {
    width: calc(100vw - 12px);
  }

  .status-row {
    width: min(360px, 100%);
    margin-bottom: 3px;
  }

  .hotbar {
    gap: 2px;
    padding: 4px;
  }

  .hotbar-slot {
    width: min(38px, calc((100vw - 52px) / 9));
    height: min(38px, calc((100vw - 52px) / 9));
  }

  .hotbar-slot canvas {
    width: 76%;
    height: 76%;
  }

  .heart {
    font-size: 14px;
  }

  .mode-chip {
    font-size: 7px;
    padding: 2px 5px;
  }

  .toast {
    font-size: 10px;
    max-width: 86vw;
    white-space: normal;
    text-align: center;
  }

  .pause-panel {
    padding: 28px 22px 24px;
  }

  .pause-panel h2 {
    font-size: 28px;
  }

  .pause-controls {
    display: none;
  }
}

@media (max-height: 680px) and (pointer: coarse) {
  .joystick {
    width: 104px;
    height: 104px;
    bottom: 82px;
  }
  .joystick-knob {
    width: 44px;
    height: 44px;
    margin: -22px 0 0 -22px;
  }
  .touch-actions {
    bottom: 88px;
    transform: scale(0.9);
    transform-origin: bottom right;
  }
  .hud-bottom {
    bottom: 4px;
  }
}

import './style.css'
import * as THREE from 'three'
import { World } from './world.js'
import { Player } from './player.js'
import { Player as _Player } from './player.js'
import { createEnvironment } from './environment.js'
import { Effects } from './effects.js'
import { AudioEngine } from './audio.js'
import { BLOCK, BLOCKS, HOTBAR } from './blocks.js'
import { atlasTexture, drawBlockIcon, uvRect } from './textures.js'

const $ = (selector) => document.querySelector(selector)
const canvas = $('#game')
const loading = $('#loading')
const loadingBar = $('#loadingBar')
const loadingText = $('#loadingText')
const titleScreen = $('#titleScreen')
const startBtn = $('#startBtn')
const hud = $('#hud')
const hotbarEl = $('#hotbar')
const heartsEl = $('#hearts')
const selectedBlockEl = $('#selectedBlock')
const coordEl = $('#coordValue')
const fpsEl = $('#fpsValue')
const modeChip = $('#modeChip')
const toastEl = $('#toast')
const pauseScreen = $('#pauseScreen')
const deathScreen = $('#deathScreen')
const deathReason = $('#deathReason')
const underwaterOverlay = $('#underwaterOverlay')
const damageOverlay = $('#damageOverlay')
const mobileControls = $('#mobileControls')
const joystick = $('#joystick')
const joystickKnob = $('#joystickKnob')
const seedLabel = $('#seedLabel')
const oxygenEl = $('#oxygen')
const oxygenPips = $('#oxygenPips')
const desktopHint = $('#desktopHint')

const params = new URLSearchParams(location.search)
const seed = Number(params.get('seed')) || 20260214
const isTouch = window.matchMedia('(any-pointer: coarse)').matches || ('ontouchstart' in window && navigator.maxTouchPoints > 0)
seedLabel.textContent = seed.toLocaleString('en-US').replace(/,/g, ' ')

const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
  powerPreference: 'high-performance',
  stencil: false,
})
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, isTouch ? 1.5 : 2))
renderer.setSize(window.innerWidth, window.innerHeight, false)
renderer.setClearColor(0xa9d6ea, 1)
atlasTexture.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy())

const scene = new THREE.Scene()
const camera = new THREE.PerspectiveCamera(70, window.innerWidth / window.innerHeight, 0.05, 360)
camera.rotation.order = 'YXZ'

const world = new World(scene, seed, isTouch ? 5 : 6)
const effects = new Effects(scene)
const audio = new AudioEngine()
const environment = createEnvironment(scene, renderer)

const spawn = world.findSpawn()
let player
let started = false
let paused = false
let pointerEverLocked = false
let mining = false
let lastDamageCause = 'the fall'
let toastTimer = 0
let selectedIndex = 0
let lastHudUpdate = 0
let frameCount = 0
let fpsClock = performance.now()
let damageHideTimer = 0
let firstFrame = true

// ---------------------------------------------------------------- held item
const handScene = new THREE.Scene()
const handCamera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.01, 10)
handCamera.position.set(0, 0, 0)
handScene.add(new THREE.AmbientLight(0xffffff, 1.45))
const handSun = new THREE.DirectionalLight(0xfff3d7, 2.2)
handSun.position.set(-1.2, 1.7, 1.3)
handScene.add(handSun)
const handRim = new THREE.DirectionalLight(0x9ed7ff, 0.65)
handRim.position.set(1.8, 0.3, -0.5)
handScene.add(handRim)

const heldRoot = new THREE.Group()
heldRoot.position.set(0.63, -0.45, -1.08)
heldRoot.rotation.set(0.12, -0.58, 0.12)
handScene.add(heldRoot)
const heldBlock = new THREE.Mesh(new THREE.BoxGeometry(0.48, 0.48, 0.48), [])
heldBlock.position.set(0, 0.02, 0)
heldRoot.add(heldBlock)
const arm = new THREE.Mesh(
  new THREE.BoxGeometry(0.26, 0.72, 0.26),
  new THREE.MeshLambertMaterial({ color: 0xc48d69 }),
)
arm.position.set(0.14, -0.45, 0.14)
arm.rotation.set(-0.25, 0.1, -0.18)
heldRoot.add(arm)
const sleeve = new THREE.Mesh(
  new THREE.BoxGeometry(0.29, 0.22, 0.29),
  new THREE.MeshLambertMaterial({ color: 0x4d7c9c }),
)
sleeve.position.set(0.14, -0.12, 0.14)
sleeve.rotation.set(-0.25, 0.1, -0.18)
heldRoot.add(sleeve)

const tileTextureCache = new Map()
function tileTexture(tile) {
  if (tileTextureCache.has(tile)) return tileTextureCache.get(tile)
  const texture = atlasTexture.clone()
  const col = tile % 8
  const row = Math.floor(tile / 8)
  texture.repeat.set(1 / 8, 1 / 8)
  texture.offset.set(col / 8, 1 - (row + 1) / 8)
  texture.needsUpdate = true
  tileTextureCache.set(tile, texture)
  return texture
}

function heldMaterials(blockId) {
  const block = BLOCKS[blockId]
  const side = new THREE.MeshLambertMaterial({ map: tileTexture(block.tiles.side) })
  const top = new THREE.MeshLambertMaterial({ map: tileTexture(block.tiles.top) })
  const bottom = new THREE.MeshLambertMaterial({ map: tileTexture(block.tiles.bottom) })
  return [side, side, top, bottom, side, side]
}
heldBlock.material = heldMaterials(HOTBAR[0])

// ---------------------------------------------------------------- UI setup
const slotCanvases = []
HOTBAR.forEach((blockId, index) => {
  const slot = document.createElement('div')
  slot.className = 'hotbar-slot'
  const icon = document.createElement('canvas')
  drawBlockIcon(icon, blockId, 38)
  const key = document.createElement('span')
  key.className = 'slot-key'
  key.textContent = String(index + 1)
  slot.append(icon, key)
  hotbarEl.append(slot)
  slotCanvases.push({ slot, icon })
})
drawBlockIcon($('#brandBlock'), BLOCK.GRASS, 28)
drawBlockIcon($('#menuBlockIcon'), BLOCK.GRASS, 118)

for (let i = 0; i < 10; i++) {
  const heart = document.createElement('span')
  heart.className = 'heart'
  heart.textContent = '♥'
  heartsEl.append(heart)
}
for (let i = 0; i < 10; i++) {
  const pip = document.createElement('span')
  pip.className = 'oxygen-pip'
  oxygenPips.append(pip)
}

function setSelected(index, announce = true) {
  selectedIndex = (index + HOTBAR.length) % HOTBAR.length
  const id = HOTBAR[selectedIndex]
  slotCanvases.forEach(({ slot }, i) => slot.classList.toggle('selected', i === selectedIndex))
  heldBlock.material = heldMaterials(id)
  selectedBlockEl.textContent = BLOCKS[id].name
  selectedBlockEl.classList.remove('pop')
  void selectedBlockEl.offsetWidth
  selectedBlockEl.classList.add('pop')
  setTimeout(() => selectedBlockEl.classList.remove('pop'), 170)
  if (announce) audio.select()
}

function updateHealth(health) {
  const hearts = heartsEl.children
  for (let i = 0; i < hearts.length; i++) {
    const value = health - i * 2
    hearts[i].className = value >= 2 ? 'heart' : value > 0 ? 'heart half' : 'heart empty'
  }
}

function updateOxygen() {
  if (!player) return
  const ratio = player.oxygen / 300
  const show = player.headInWater || ratio < 0.99
  oxygenEl.classList.toggle('is-hidden', !show)
  const pips = oxygenPips.children
  for (let i = 0; i < pips.length; i++) pips[i].classList.toggle('off', i / pips.length > ratio)
}

function showToast(text, duration = 2400) {
  toastEl.textContent = text
  toastEl.classList.add('show')
  clearTimeout(toastTimer)
  toastTimer = setTimeout(() => toastEl.classList.remove('show'), duration)
}

function flashDamage() {
  damageOverlay.style.opacity = '0.82'
  clearTimeout(damageHideTimer)
  damageHideTimer = setTimeout(() => { damageOverlay.style.opacity = '0' }, 130)
}

function setModeChip() {
  modeChip.textContent = player?.flying ? 'FLYING' : 'SURVIVAL'
  modeChip.classList.toggle('flying', Boolean(player?.flying))
}

function showPause() {
  if (!started || paused || player.dead) return
  paused = true
  pauseScreen.classList.remove('is-hidden')
  mining = false
  player.input.jump = false
  if (document.pointerLockElement) document.exitPointerLock()
}

function hidePause(requestLock = true) {
  paused = false
  pauseScreen.classList.add('is-hidden')
  canvas.focus()
  if (requestLock && !isTouch) requestPointerLock()
}

function requestPointerLock() {
  if (isTouch || document.pointerLockElement === canvas) return
  try {
    const promise = canvas.requestPointerLock()
    if (promise?.catch) promise.catch(() => {})
  } catch {}
}

function triggerSwing() {
  swingRemaining = 0.3
}
let swingRemaining = 0

function placeSelectedBlock() {
  if (!player) return
  player.updateTarget(true)
  const blockId = HOTBAR[selectedIndex]
  const placed = player.placeBlock(blockId, true, () => triggerSwing())
  if (!placed) triggerSwing()
}

// ---------------------------------------------------------------- start & pause
function beginGame() {
  if (started) return
  started = true
  audio.init()
  audio.click()
  titleScreen.classList.add('is-hidden')
  hud.classList.remove('is-hidden')
  loading.classList.add('is-hidden')
  if (isTouch) mobileControls.classList.remove('is-hidden')
  canvas.focus()
  if (!isTouch) requestPointerLock()
  setTimeout(() => {
    if (!paused && !player.dead) showToast(isTouch ? 'Drag to look · joystick to move' : 'WASD to move · hold left click to mine', 2600)
  }, 1800)
}

startBtn.addEventListener('click', beginGame)
canvas.addEventListener('click', () => {
  if (!started || paused || player?.dead) return
  if (!isTouch && !document.pointerLockElement) requestPointerLock()
})
$('#resumeBtn').addEventListener('click', () => hidePause(true))
$('#pauseMuteBtn').addEventListener('click', toggleMute)
$('#muteBtn').addEventListener('click', toggleMute)
$('#respawnBtn').addEventListener('click', () => {
  player.respawn()
  hidePause(true)
  showToast('Back at the shoreline', 1800)
})
$('#deathRespawn').addEventListener('click', () => {
  player.respawn()
  deathScreen.classList.add('is-hidden')
  paused = false
  if (!isTouch) requestPointerLock()
})
$('#seedLabel').addEventListener('click', () => {
  navigator.clipboard?.writeText(String(seed)).then(() => showToast('Seed copied'))
})

function toggleMute() {
  audio.init()
  audio.setMuted(!audio.muted)
  const label = audio.muted ? 'Sound: Off' : 'Sound: On'
  $('#pauseMuteBtn').textContent = label
  $('#muteBtn').textContent = audio.muted ? 'SOUND OFF' : 'SOUND ON'
  if (started) showToast(audio.muted ? 'Sound muted' : 'Sound on', 1200)
}

document.addEventListener('pointerlockchange', () => {
  if (document.pointerLockElement === canvas) {
    pointerEverLocked = true
    if (paused) hidePause(false)
  } else if (started && pointerEverLocked && !player.dead && !paused) {
    showPause()
  }
})

document.addEventListener('visibilitychange', () => {
  if (document.hidden && started && !paused && !player.dead) showPause()
})

// ---------------------------------------------------------------- input
const inputMap = {
  KeyW: 'forward', ArrowUp: 'forward',
  KeyS: 'back', ArrowDown: 'back',
  KeyA: 'left', ArrowLeft: 'left',
  KeyD: 'right', ArrowRight: 'right',
  Space: 'jump',
  ShiftLeft: 'sprint', ShiftRight: 'sprint',
  ControlLeft: 'descend', ControlRight: 'descend',
}

window.addEventListener('keydown', (event) => {
  if (!started) return
  if (event.code === 'Escape') return
  if (event.code === 'KeyM') {
    toggleMute()
    event.preventDefault()
    return
  }
  if (event.code === 'KeyF' && !event.repeat) {
    const flying = player.toggleFly()
    setModeChip()
    showToast(flying ? 'Flight enabled — Space up, Ctrl down' : 'Flight disabled', 1900)
    event.preventDefault()
    return
  }
  if (event.code === 'KeyR' && player.dead) {
    player.respawn()
    deathScreen.classList.add('is-hidden')
    paused = false
    return
  }
  const mapped = inputMap[event.code]
  if (mapped) {
    player.input[mapped] = true
    event.preventDefault()
  }
  if (event.code.startsWith('Digit')) {
    const index = Number(event.code.slice(5)) - 1
    if (index >= 0 && index < HOTBAR.length) {
      setSelected(index)
      event.preventDefault()
    }
  }
})

window.addEventListener('keyup', (event) => {
  if (!player) return
  const mapped = inputMap[event.code]
  if (mapped) {
    player.input[mapped] = false
    event.preventDefault()
  }
})

window.addEventListener('blur', () => {
  if (!player) return
  for (const key of Object.values(player.input)) {
    if (typeof key === 'boolean') {
      // only reset booleans; joystick values are handled separately
    }
  }
  player.input.forward = false
  player.input.back = false
  player.input.left = false
  player.input.right = false
  player.input.jump = false
  player.input.sprint = false
  player.input.descend = false
  mining = false
})

window.addEventListener('wheel', (event) => {
  if (!started || paused || player.dead) return
  if (event.deltaY !== 0) {
    setSelected(selectedIndex + (event.deltaY > 0 ? 1 : -1))
    event.preventDefault()
  }
}, { passive: false })

canvas.addEventListener('contextmenu', (event) => event.preventDefault())
canvas.addEventListener('pointerdown', (event) => {
  if (!started || paused || player.dead) return
  if (event.pointerType === 'touch') return
  if (!isTouch && !document.pointerLockElement) {
    requestPointerLock()
    return
  }
  if (event.button === 0) {
    mining = true
    triggerSwing()
    player.updateTarget(true)
  } else if (event.button === 2) {
    placeSelectedBlock()
  }
})
window.addEventListener('pointerup', (event) => {
  if (event.button === 0 || event.pointerType === 'touch') mining = false
})

document.addEventListener('mousemove', (event) => {
  if (!started || paused || player.dead || isTouch) return
  if (document.pointerLockElement === canvas) {
    player.look(event.movementX, event.movementY)
  }
})

// ---------------------------------------------------------------- touch controls
if (isTouch) {
  const activeTouches = new Map()
  canvas.addEventListener('touchstart', (event) => {
    if (!started || paused || player.dead) return
    for (const touch of event.changedTouches) {
      if (activeTouches.size === 0) {
        activeTouches.set(touch.identifier, { x: touch.clientX, y: touch.clientY, look: true })
        event.preventDefault()
      }
    }
  }, { passive: false })
  canvas.addEventListener('touchmove', (event) => {
    if (!started || paused || player.dead) return
    for (const touch of event.changedTouches) {
      const state = activeTouches.get(touch.identifier)
      if (!state) continue
      const dx = touch.clientX - state.x
      const dy = touch.clientY - state.y
      state.x = touch.clientX
      state.y = touch.clientY
      player.look(dx, dy, 0.0042)
      event.preventDefault()
    }
  }, { passive: false })
  const endTouch = (event) => {
    for (const touch of event.changedTouches) activeTouches.delete(touch.identifier)
  }
  canvas.addEventListener('touchend', endTouch)
  canvas.addEventListener('touchcancel', endTouch)

  let joystickPointer = null
  const updateJoystick = (event) => {
    if (event.pointerId !== joystickPointer) return
    const rect = joystick.getBoundingClientRect()
    const cx = rect.left + rect.width / 2
    const cy = rect.top + rect.height / 2
    let dx = event.clientX - cx
    let dy = event.clientY - cy
    const radius = rect.width * 0.33
    const length = Math.hypot(dx, dy)
    if (length > radius) {
      dx = (dx / length) * radius
      dy = (dy / length) * radius
    }
    joystickKnob.style.transform = `translate(${dx}px, ${dy}px)`
    player.setTouchMove(dx / radius, -dy / radius)
    event.preventDefault()
  }
  joystick.addEventListener('pointerdown', (event) => {
    joystickPointer = event.pointerId
    joystick.setPointerCapture(event.pointerId)
    updateJoystick(event)
    event.stopPropagation()
    event.preventDefault()
  })
  joystick.addEventListener('pointermove', (event) => {
    updateJoystick(event)
    event.stopPropagation()
  })
  const releaseJoystick = (event) => {
    if (event.pointerId !== joystickPointer) return
    joystickPointer = null
    joystickKnob.style.transform = ''
    player?.setTouchMove(0, 0)
    event.stopPropagation()
  }
  joystick.addEventListener('pointerup', releaseJoystick)
  joystick.addEventListener('pointercancel', releaseJoystick)

  const bindHold = (id, down, up) => {
    const element = $(id)
    element.addEventListener('pointerdown', (event) => {
      event.stopPropagation()
      event.preventDefault()
      element.setPointerCapture(event.pointerId)
      element.classList.add('pressed')
      down()
    })
    const release = (event) => {
      event.stopPropagation()
      element.classList.remove('pressed')
      up?.()
    }
    element.addEventListener('pointerup', release)
    element.addEventListener('pointercancel', release)
  }
  bindHold('#jumpBtn', () => { player.input.jump = true }, () => { player.input.jump = false })
  bindHold('#breakBtn', () => {
    mining = true
    triggerSwing()
    player.updateTarget(true)
  }, () => { mining = false })
  const placeBtn = $('#placeBtn')
  placeBtn.addEventListener('pointerdown', (event) => {
    event.stopPropagation()
    event.preventDefault()
    placeBtn.classList.add('pressed')
    placeSelectedBlock()
  })
  placeBtn.addEventListener('pointerup', () => placeBtn.classList.remove('pressed'))
  placeBtn.addEventListener('pointercancel', () => placeBtn.classList.remove('pressed'))
}

// ---------------------------------------------------------------- player wiring
function updateHud(now) {
  const elapsed = now - lastHudUpdate
  if (elapsed < 180) return
  lastHudUpdate = now
  coordEl.textContent = `${Math.floor(player.position.x)} · ${Math.floor(player.position.y)} · ${Math.floor(player.position.z)}`
  underwaterOverlay.classList.toggle('active', player.headInWater)
  updateOxygen()
  if (player.oxygen < 90 && player.headInWater) underwaterOverlay.classList.add('danger')
  else underwaterOverlay.classList.remove('danger')
}

function onResize() {
  const width = window.innerWidth
  const height = window.innerHeight
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, isTouch ? 1.5 : 2))
  renderer.setSize(width, height, false)
  camera.aspect = width / height
  camera.updateProjectionMatrix()
  handCamera.aspect = width / height
  handCamera.updateProjectionMatrix()
}
window.addEventListener('resize', onResize)

// ---------------------------------------------------------------- boot
async function boot() {
  loadingText.textContent = 'Carving rivers and ridgelines…'
  loadingBar.style.width = '24%'
  await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)))
  const spawnChunkX = Math.floor(spawn.x / 16)
  const spawnChunkZ = Math.floor(spawn.z / 16)
  world.ensureArea(spawnChunkX, spawnChunkZ, world.renderDistance)

  loadingText.textContent = 'Planting the last oak…'
  loadingBar.style.width = '78%'
  await new Promise((resolve) => requestAnimationFrame(resolve))

  player = new Player({ world, scene, camera, spawn, audio, effects })
  player.look(0, 0)
  const focus = new THREE.Vector3(-11, spawn.y + 5, -33)
  player.yaw = Math.atan2(-(focus.x - spawn.x), -(focus.z - spawn.z))
  player.pitch = -0.075
  player.updateCamera(0.016)
  player.selected = HOTBAR[0]
  player.onDeath = () => {
    deathReason.textContent = lastDamageCause === 'drown' ? 'The water pulled you under.' : lastDamageCause === 'void' ? 'You fell out of the world.' : 'The fall was too far.'
    deathScreen.classList.remove('is-hidden')
    mining = false
    if (document.pointerLockElement) document.exitPointerLock()
  }
  player.onDamage = (amount, cause) => {
    lastDamageCause = cause
    flashDamage()
  }
  player.onHealthChanged = updateHealth
  updateHealth(player.health)
  setSelected(0, false)
  setModeChip()

  loadingText.textContent = 'Waking the morning…'
  loadingBar.style.width = '100%'
  await new Promise((resolve) => setTimeout(resolve, 260))
  loading.classList.add('is-hidden')
  startBtn.disabled = false
  requestAnimationFrame(loop)
}

let last = performance.now()
let environmentTime = 0
let initialFrames = 0

function loop(now) {
  requestAnimationFrame(loop)
  const dt = Math.min(0.05, Math.max(0.001, (now - last) / 1000))
  last = now
  environmentTime = environment.update(player ? player.getEyePosition().clone() : camera.position)

  const active = started && !paused && !player.dead && !document.hidden
  if (player && active) {
    player.update(dt)
    player.updateMining(dt, true, mining, () => {})
    if (player.inWater !== underwaterOverlay.classList.contains('active')) {
      underwaterOverlay.classList.toggle('active', player.inWater)
    }
  } else if (player) {
    player.highlight.visible = false
    player.crackMesh.visible = false
    player.updateCamera(dt)
  }

  effects.update(dt)
  updateHeldItem(dt)
  updateHud(now)

  frameCount++
  if (now - fpsClock > 600) {
    fpsEl.textContent = Math.round((frameCount * 1000) / (now - fpsClock))
    frameCount = 0
    fpsClock = now
  }

  renderer.clear()
  renderer.render(scene, camera)
  renderer.clearDepth()
  renderer.render(handScene, handCamera)

  if (firstFrame) {
    firstFrame = false
    startBtn.disabled = false
  }
  initialFrames++
}

function updateHeldItem(dt) {
  const bob = player ? player.bob : 0
  const idle = Math.sin(environmentTime * 1.6) * 0.008
  let lift = 0
  let tilt = 0
  let roll = 0
  if (swingRemaining > 0) {
    swingRemaining = Math.max(0, swingRemaining - dt)
    const t = 1 - swingRemaining / 0.3
    const arc = Math.sin(t * Math.PI)
    lift = arc * 0.12
    tilt = arc * -0.5
    roll = arc * 0.18
  }
  heldRoot.position.set(0.63, -0.45 + bob * 1.4 + idle + lift, -1.08)
  heldRoot.rotation.set(0.12 + tilt, -0.58, 0.12 + roll)
  arm.position.y = -0.45 + lift * 0.35
}

startBtn.disabled = true
boot().catch((error) => {
  console.error(error)
  loadingText.textContent = 'The world failed to load. Reload to try again.'
})

